const HTML="<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#090a0b\">\n  <title>CEO Notes | ملاحظات يومية في الإدارة والقيادة</title>\n  <meta name=\"description\" content=\"CEO Notes — أفكار عملية عن القيادة والإدارة والعمل الذكي، في مقالات يومية قصيرة قابلة للتطبيق.\">\n  <link rel=\"canonical\" href=\"https://ceo-notes.pages.dev/\">\n  <link rel=\"alternate\" type=\"application/rss+xml\" title=\"CEO Notes RSS\" href=\"https://ceo-notes.pages.dev/rss.xml\">\n  <meta name=\"robots\" content=\"index,follow\">\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:title\" content=\"CEO Notes | ملاحظات يومية في الإدارة والقيادة\">\n  <meta property=\"og:description\" content=\"أفكار عملية عن القيادة والإدارة والعمل الذكي.\">\n  <meta property=\"og:url\" content=\"https://ceo-notes.pages.dev/\">\n  <meta property=\"og:image\" content=\"https://ceo-notes.pages.dev/ceo-notes-social.svg\">\n  <meta property=\"article:published_time\" content=\"\">\n  <meta property=\"article:section\" content=\"\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\">\n  <meta name=\"twitter:title\" content=\"CEO Notes | ملاحظات يومية في الإدارة والقيادة\">\n  <meta name=\"twitter:description\" content=\"أفكار عملية عن القيادة والإدارة والعمل الذكي.\">\n  <meta name=\"twitter:image\" content=\"https://ceo-notes.pages.dev/ceo-notes-social.svg\">\n  <style>:root{color-scheme:dark;--bg:#0b0d0f;--gold:#c5a36b;--gold2:#ead6ad;--ink:#f5f2eb;--muted:#a8aaa6;--line:#ffffff18;--max:1160px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:radial-gradient(ellipse at 80% 0%,#c5a36b12,transparent 34%),var(--bg);color:var(--ink);font-family:system-ui,-apple-system,\"Segoe UI\",Tahoma,Arial,sans-serif;line-height:1.8}a{color:inherit;text-decoration:none}button,input,select{font:inherit}.wrap{width:min(var(--max),92%);margin-inline:auto}.topbar{position:sticky;top:0;z-index:20;border-bottom:1px solid var(--line);background:#0b0d0fee;backdrop-filter:blur(16px)}.nav{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:22px}.brand{display:flex;align-items:center;gap:13px}.mark{width:45px;height:45px;border:1px solid #c5a36b99;border-radius:50%;display:grid;place-items:center;color:var(--gold2);font:700 15px Georgia;background:#171b1b}.brand-name{display:grid;line-height:1.25}.brand-name strong{font-size:15px;letter-spacing:3px}.brand-name small{font-size:9px;color:var(--gold);letter-spacing:1.8px;margin-top:5px}.navlinks{display:flex;gap:25px;color:#c8c8c1;font-size:12px}.navlinks a:hover{color:var(--gold2)}.hero{position:relative;overflow:hidden;padding:clamp(65px,10vw,125px) 0;border-bottom:1px solid var(--line);background:linear-gradient(110deg,#101619,#0b0d0f 70%)}.hero:after{content:\"CN\";position:absolute;inset-inline-end:3%;top:2%;font:clamp(170px,30vw,390px)/1 Georgia;color:#ffffff06;pointer-events:none}.hero .wrap{position:relative;z-index:1;text-align:start}.eyebrow{display:inline-flex;gap:10px;color:var(--gold2);font-size:10px;letter-spacing:2px}.eyebrow:before{content:\"\";width:27px;height:1px;background:var(--gold);align-self:center}h1{max-width:850px;font:500 clamp(42px,7.4vw,86px)/1.16 Georgia;letter-spacing:-1.6px;margin:20px 0}.hero h1 span{color:var(--gold2)}.hero p{max-width:670px;color:#c2c4bf;font-size:clamp(14px,1.5vw,17px);line-height:2}.hero-note{display:inline-flex;margin-top:20px;padding:8px 14px;border-inline-start:2px solid var(--gold);background:#ffffff08;color:#d6c9af;font-size:11px}#latest{padding-top:66px}.toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:20px}.section-title{font:500 clamp(27px,3.5vw,38px)/1.25 Georgia;margin:0}.count{color:var(--muted);font-size:11px}.archive-tools{display:flex;gap:8px;width:min(520px,100%)}.search,.category-select{min-width:0;background:#111619;border:1px solid var(--line);border-radius:4px;padding:11px 13px;color:var(--ink);font-size:12px}.search{flex:1}.category-select{min-width:145px}.tag-filters{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:22px}.tag-filter{border:1px solid var(--line);background:transparent;color:#c9c9c2;border-radius:3px;padding:6px 11px;font-size:10px;cursor:pointer}.tag-filter[aria-pressed=true]{border-color:var(--gold);background:#c5a36b18;color:var(--gold2)}.posts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding-bottom:75px}.post{background:linear-gradient(145deg,#151b1e,#101416);border:1px solid var(--line);border-radius:5px;padding:23px;min-width:0;transition:border-color .2s,transform .2s}.post:hover{border-color:#c5a36b70;transform:translateY(-2px)}.post:first-child{grid-column:1/-1;padding:clamp(24px,4vw,42px);background:linear-gradient(110deg,#1a211f,#111719 72%);border-color:#c5a36b50}.post-top{display:flex;justify-content:space-between;gap:12px;margin-bottom:13px}.day{color:var(--gold2);font-size:10px;letter-spacing:1.4px;font-weight:700}.date{color:#8f9692;font-size:10px}.post h3{font:500 21px/1.55 Georgia;margin:0 0 13px;color:#f0e8d8}.post:first-child h3{font-size:clamp(25px,3.2vw,37px)}.article{white-space:pre-line;color:#c4c8c3;font-size:13px;line-height:2.05}.post:first-child .article{font-size:14px}.post-actions{display:flex;margin-top:17px}.share-button{border:1px solid #c5a36b75;background:#c5a36b12;color:var(--gold2);border-radius:3px;padding:8px 14px;font-size:11px;cursor:pointer}.detail{border-top:1px solid var(--line);margin-top:18px;padding-top:15px;display:grid;gap:12px}.detail-block{font-size:12px;color:#c8c9c3}.detail-block strong{display:block;color:var(--gold2);font-size:10px}.hashtags,.topic-tags{display:flex;flex-wrap:wrap;gap:7px}.tag,.post-category,.topic-tag{color:#d8c69f;font-size:10px;border:1px solid #c5a36b30;border-radius:3px;padding:3px 8px}.empty{grid-column:1/-1;text-align:center;padding:48px 22px;border:1px dashed #ffffff35;color:var(--muted)}.about{border-block:1px solid var(--line);background:#111719;padding:48px 0}.about-inner{max-width:790px;margin:auto;text-align:center}.about h2{font:500 30px Georgia}.about p{color:#b4b9b4;font-size:13px}.tools-area{padding:64px 0 20px;background:#0d1113}.tools-intro{text-align:center;margin-bottom:30px}.tools-intro h2{font:500 clamp(25px,3vw,34px) Georgia;margin:8px}.tools-intro p{color:var(--muted);font-size:12px}.market-watch,.world-clock,.radio-section{padding:25px 0 32px}.market-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.market-card,.clock{background:#141a1d;border:1px solid var(--line);border-radius:4px;padding:14px}.market-label,.clock-city{font-size:10px;color:#d8c69f}.market-value,.clock-time{font-size:clamp(17px,2.4vw,23px);font-weight:700;direction:ltr;text-align:right}.market-unit,.clock-date,.market-note,.clock-zone{font-size:10px;color:var(--muted)}.clock-heading{display:flex;justify-content:space-between;margin-bottom:15px}.clock-heading h2{font:500 22px Georgia}.clock-heading p{font-size:10px;color:var(--muted)}.clocks{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}footer{padding:23px 0;color:#858c88;font-size:10px;border-top:1px solid var(--line)}.footer-row{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}.skip-link{position:absolute;top:-60px;inset-inline-start:12px;background:var(--gold2);color:#111;padding:8px;z-index:100}.skip-link:focus{top:8px}@media(max-width:760px){.nav{min-height:68px}.navlinks{gap:13px;font-size:10px}.brand-name strong{font-size:13px}.hero{padding:64px 0 58px}.toolbar{align-items:stretch;flex-direction:column}.archive-tools{width:100%}.posts{grid-template-columns:1fr}.post:first-child{grid-column:auto}.market-grid,.clocks{grid-template-columns:repeat(2,minmax(0,1fr))}.clock:last-child{grid-column:1/-1}}@media(max-width:480px){.navlinks a:last-child{display:none}.archive-tools{flex-direction:column}.search,.category-select{width:100%}.post{padding:19px}.footer-row{flex-direction:column}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.post{transition:none}}</style>\n  <link rel=\"stylesheet\" href=\"/radio.css\">\n</head>\n<body><a class=\"skip-link\" href=\"#latest\">تجاوز إلى المقالات</a>\n  <header class=\"topbar\">\n    <div class=\"wrap nav\">\n      <a class=\"brand\" href=\"/\" aria-label=\"CEO Notes\">\n        <span class=\"mark\" aria-hidden=\"true\">CN</span>\n        <span class=\"brand-name\"><strong>CEO NOTES</strong><small>LEADERSHIP · BUSINESS · MINDSET</small></span>\n      </a>\n      <nav class=\"navlinks\" aria-label=\"التنقل\">\n        <a href=\"#latest\">المقالات</a>\n        <a href=\"#business-tools\">الأدوات</a>\n        <a href=\"#about\">عن السلسلة</a>\n        <a href=\"https://www.facebook.com/115226621594988/\" target=\"_blank\" rel=\"noopener noreferrer\">صفحة فيسبوك</a>\n      </nav>\n    </div>\n  </header>\n\n  <main><section class=\"hero\">\n      <div class=\"wrap\">\n        <div class=\"eyebrow\">ملاحظات من أرض الواقع</div>\n        <h1>فكر أوضح.<br><span>وقُد بوعي أكبر.</span></h1>\n        <p>مساحة يومية لأفكار عملية عن القيادة والإدارة والعمل الذكي. مش شعارات محفوظة؛ ملاحظات تساعدك تشوف المشكلة من زاوية مختلفة وتحوّل الفكرة لخطوة قابلة للتنفيذ.</p>\n        <div class=\"hero-note\">مقال جديد كل يوم · فكرة · تحدٍ عملي · نقاش</div>\n      </div>\n    </section><section class=\"wrap\" id=\"latest\">\n      <div id=\"archive-controls\">\n        <div class=\"toolbar\">\n          <div>\n            <h2 class=\"section-title\">أحدث الملاحظات</h2>\n            <div class=\"count\" id=\"count\" aria-live=\"polite\">جارٍ تحميل المقالات…</div>\n          </div>\n          <div class=\"archive-tools\">\n            <input class=\"search\" id=\"search\" type=\"search\" placeholder=\"ابحث في العناوين والمقالات…\" aria-label=\"ابحث في المقالات\">\n            <select class=\"category-select\" id=\"category-filter\" aria-label=\"تصفية المقالات حسب القسم\">\n              <option value=\"\">كل الأقسام</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"tag-filters\" id=\"tag-filters\" aria-label=\"تصفية المقالات حسب الموضوع\"></div>\n      </div>\n      <div class=\"posts\" id=\"posts\" aria-live=\"polite\">\n        <div class=\"empty\"><strong>لحظة واحدة…</strong>بنجهز أحدث الملاحظات للعرض.</div>\n      </div>\n    </section><section class=\"about\" id=\"about\">\n      <div class=\"wrap about-inner\">\n        <h2>عن CEO Notes</h2>\n        <p>سلسلة مستقلة تناقش مواقف العمل والقيادة من منظور عملي. كل مقال يقدّم فكرة واضحة، وتطبيقًا صغيرًا، وسؤالًا يفتح باب التفكير والنقاش.</p>\n        <p style=\"margin-top:18px\"><a href=\"https://www.facebook.com/115226621594988/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;padding:10px 18px;border:1px solid #c8a568;border-radius:30px;color:#e5cc98\">تابع CEO Notes على Facebook</a></p>\n      </div>\n    </section><section class=\"tools-area\" id=\"business-tools\"><div class=\"wrap tools-intro\"><span class=\"eyebrow\">مساحة مساندة</span><h2>أدوات تساعدك على متابعة العالم</h2><p>موارد إضافية للمتابعة والاستماع — دون أن تزاحم الفكرة الأساسية.</p></div><section class=\"wrap market-watch\" aria-labelledby=\"market-title\">\n      <div class=\"clock-heading\">\n        <div>\n          <h2 id=\"market-title\">مؤشرات العملات والذهب</h2>\n          <p>أسعار مرجعية يومية من مصادر مفتوحة</p>\n        </div>\n        <div class=\"market-updated\" id=\"market-updated\" aria-live=\"polite\">جارٍ تحميل البيانات…</div>\n      </div>\n      <div class=\"market-grid\" id=\"market-board\" aria-live=\"polite\">\n        <div class=\"market-card\"><div class=\"market-label\">أسعار العملات</div><div class=\"market-value\">—</div><div class=\"market-unit\">جارٍ التحميل</div></div>\n      </div>\n      <p class=\"market-note\">الأسعار مرجعية يومية وليست أسعار تداول لحظية أو أسعار شراء وبيع البنوك. قيمة الذهب محسوبة من أونصة تروي XAU، ولا تمثل سعر المشغولات أو السعر المحلي بعد المصنعية والضرائب. المصدر: <a href=\"https://frankfurter.dev/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:var(--gold2)\">Frankfurter</a>.</p>\n    </section><section class=\"wrap world-clock\" aria-labelledby=\"clock-title\">\n      <div class=\"clock-heading\">\n        <div>\n          <h2 id=\"clock-title\">ساعات الأعمال حول العالم</h2>\n          <p>توقيت مباشر حسب المناطق الزمنية الرسمية، دون API أو اشتراك خارجي.</p>\n        </div>\n      </div>\n      <div class=\"clocks\" id=\"world-clocks\">\n        <div class=\"clock\"><div class=\"clock-city\">القاهرة</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Africa/Cairo</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">لندن</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Europe/London</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">نيويورك</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">America/New_York</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">موسكو</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Europe/Moscow</div></div>\n        <div class=\"clock\"><div class=\"clock-city\">دبي</div><div class=\"clock-time\">--:--:--</div><div class=\"clock-zone\">Asia/Dubai</div></div>\n      </div>\n    </section><section class=\"wrap radio-section\" id=\"radio\" aria-labelledby=\"radio-title\">\n      <div class=\"radio-panel\" id=\"ceo-radio\">\n        <div class=\"radio-head\">\n          <div><h2 id=\"radio-title\">راديو CEO Notes</h2><p>اكتشف محطات إذاعية مجانية من مصر والعالم، واستمع مباشرة من مصدر البث.</p></div>\n          <span class=\"radio-free\">مجاني · بدون تسجيل</span>\n        </div>\n        <form class=\"radio-controls\" id=\"radio-form\">\n          <input class=\"radio-input\" id=\"radio-search\" type=\"search\" maxlength=\"100\" placeholder=\"ابحث باسم محطة إذاعية…\" aria-label=\"ابحث عن محطة إذاعية\">\n          <select class=\"radio-country\" id=\"radio-country\" aria-label=\"اختر الدولة\"><option value=\"\">كل الدول</option><option value=\"Egypt\">مصر</option><option value=\"United Arab Emirates\">الإمارات</option><option value=\"Saudi Arabia\">السعودية</option><option value=\"United Kingdom\">بريطانيا</option><option value=\"The United States Of America\">الولايات المتحدة</option></select>\n          <button class=\"radio-search-btn\" type=\"submit\">ابحث عن محطات</button>\n        </form>\n        <div class=\"radio-presets\" aria-label=\"تصنيفات الراديو\">\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"\" aria-pressed=\"true\">الأكثر استماعًا</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"arabic\" aria-pressed=\"false\">عربي</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"news\" aria-pressed=\"false\">أخبار</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"jazz\" aria-pressed=\"false\">جاز</button>\n          <button class=\"radio-filter\" type=\"button\" data-radio-tag=\"pop\" aria-pressed=\"false\">موسيقى</button>\n        </div>\n        <p class=\"radio-status\" id=\"radio-status\" role=\"status\" aria-live=\"polite\">اختر تصنيفًا أو ابحث عن محطة لبدء الاستماع.</p>\n        <div class=\"radio-results\" id=\"radio-results\"><div class=\"radio-empty\">المحطات ستظهر هنا بعد البحث.</div></div>\n        <div class=\"radio-player\">\n          <div class=\"radio-now\"><strong>يعمل الآن</strong><span id=\"radio-now-name\">لم يتم اختيار محطة</span><span id=\"radio-now-country\">اختر محطة من القائمة</span></div>\n          <audio id=\"radio-audio\" controls preload=\"none\" aria-label=\"مشغل الراديو\"></audio>\n        </div>\n        <p class=\"radio-disclaimer\">المحطات وروابط البث مقدمة من دليل Radio Browser المفتوح. الصوت يأتي مباشرة من خوادم المحطات؛ لا يستضيف CEO Notes البث ولا يسجله أو يعيد توزيعه. قد تتوقف بعض المحطات أو تقيّد الاستماع حسب الدولة. لأمان الموقع، نعرض روابط البث الآمنة HTTPS فقط. <a href=\"https://www.radio-browser.info/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:var(--gold2)\">المصدر والترخيص</a>.</p>\n      </div>\n    </section></section></main>\n\n  <footer>\n    <div class=\"wrap footer-row\">\n      <span>© <span id=\"year\"></span> CEO Notes</span>\n      <span>أفكار عملية. قرارات أوضح. أثر يدوم.</span>\n    </div>\n  </footer>\n\n  <script>\n    (function(){\n      \"use strict\";\n      const list = document.getElementById(\"posts\");\n      const search = document.getElementById(\"search\");\n      const categoryFilter = document.getElementById(\"category-filter\");\n      const tagFilters = document.getElementById(\"tag-filters\");\n      const archiveControls = document.getElementById(\"archive-controls\");\n      const count = document.getElementById(\"count\");\n      const marketBoard = document.getElementById(\"market-board\");\n      const marketUpdated = document.getElementById(\"market-updated\");\n      function marketCard(label,value,unit){\n        const card=node(\"div\",\"market-card\");\n        card.append(node(\"div\",\"market-label\",label));\n        card.append(node(\"div\",\"market-value\",value));\n        card.append(node(\"div\",\"market-unit\",unit));\n        return card;\n      }\n      async function loadMarkets(){\n        try{\n          const response=await fetch(\"/markets\",{cache:\"no-store\",headers:{\"Accept\":\"application/json\"}});\n          if(!response.ok) throw new Error(\"market_data_unavailable\");\n          const data=await response.json();\n          const fx=Object.fromEntries((Array.isArray(data.fx)?data.fx:[]).map(item=>[item.quote,Number(item.rate)]));\n          const gold=Object.fromEntries((Array.isArray(data.gold)?data.gold:[]).map(item=>[item.quote,Number(item.rate)]));\n          const fmt=(value,digits=4)=>Number(value).toLocaleString(\"en-US\",{maximumFractionDigits:digits});\n          const cards=[];\n          const pairs=[\n            [\"دولار / جنيه مصري\",\"EGP\",\"جنيه لكل دولار\",3],\n            [\"دولار / يورو\",\"EUR\",\"يورو لكل دولار\",4],\n            [\"دولار / إسترليني\",\"GBP\",\"إسترليني لكل دولار\",4],\n            [\"دولار / روبل\",\"RUB\",\"روبل لكل دولار\",2],\n            [\"دولار / درهم إماراتي\",\"AED\",\"درهم لكل دولار\",4],\n            [\"دولار / ريال سعودي\",\"SAR\",\"ريال لكل دولار\",4]\n          ];\n          pairs.forEach(([label,code,unit,digits])=>{\n            if(Number.isFinite(fx[code])) cards.push(marketCard(label,fmt(fx[code],digits),unit));\n          });\n          if(Number.isFinite(gold.USD)) cards.push(marketCard(\"أونصة الذهب\",\"$\"+fmt(gold.USD,2),\"دولار أمريكي / أونصة تروي\"));\n          if(Number.isFinite(gold.EGP)){\n            cards.push(marketCard(\"أونصة الذهب\",\"ج.م \"+fmt(gold.EGP,0),\"جنيه مصري / أونصة تروي\"));\n            cards.push(marketCard(\"جرام ذهب 24 قيراط\",\"ج.م \"+fmt(gold.EGP/31.1034768,2),\"قيمة مرجعية محسوبة قبل المصنعية والضرائب\"));\n          }\n          if(!cards.length) throw new Error(\"empty_market_data\");\n          marketBoard.replaceChildren(...cards);\n          const checked=data.fetchedAt?new Date(data.fetchedAt).toLocaleString(\"ar-EG\",{dateStyle:\"short\",timeStyle:\"short\"}):\"غير معروف\";\n          marketUpdated.classList.toggle(\"is-stale\",Boolean(data.stale));\n          marketUpdated.textContent=data.stale?\"بيانات قديمة — آخر تحديث: \"+checked+\" — تاريخ المصدر: \"+String(data.date||\"غير متاح\"):\"تاريخ المصدر: \"+String(data.date||\"غير متاح\")+\" — آخر تحديث: \"+checked;\n        }catch(error){\n          marketBoard.replaceChildren();\n          marketBoard.append(node(\"div\",\"empty\",\"تعذر تحميل المؤشرات حاليًا. حاول مرة أخرى لاحقًا.\"));\n          marketUpdated.classList.add(\"is-stale\");marketUpdated.textContent=\"لا توجد بيانات حديثة أو محفوظة حاليًا\";\n        }\n      }\n      loadMarkets();\n      const clockRoot = document.getElementById(\"world-clocks\");\n      document.getElementById(\"year\").textContent = String(new Date().getFullYear());\n      const clockFormatters = [\n        {zone:\"Africa/Cairo\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Africa/Cairo\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Africa/Cairo\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Europe/London\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/London\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/London\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"America/New_York\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"America/New_York\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"America/New_York\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Europe/Moscow\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/Moscow\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Europe/Moscow\",weekday:\"short\",day:\"2-digit\",month:\"short\"})},\n        {zone:\"Asia/Dubai\",time:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Asia/Dubai\",hour:\"2-digit\",minute:\"2-digit\",second:\"2-digit\",hour12:false}),date:new Intl.DateTimeFormat(\"en-GB\",{timeZone:\"Asia/Dubai\",weekday:\"short\",day:\"2-digit\",month:\"short\"})}\n      ];\n      function updateWorldClocks(){\n        const now = new Date();\n        clockRoot.querySelectorAll(\".clock\").forEach((card,index)=>{\n          const item = clockFormatters[index];\n          if(!item) return;\n          card.querySelector(\".clock-time\").textContent = item.time.format(now);\n          card.querySelector(\".clock-date\").textContent = item.date.format(now);\n        });\n      }\n      clockRoot.querySelectorAll(\".clock\").forEach((card,index)=>{\n        const date = document.createElement(\"div\");\n        date.className = \"clock-date\";\n        card.append(date);\n        const zone = document.createElement(\"div\");\n        zone.className = \"clock-zone\";\n        zone.textContent = clockFormatters[index].zone;\n        card.querySelector(\".clock-zone\").replaceWith(zone);\n      });\n      updateWorldClocks();\n      window.setInterval(updateWorldClocks,1000);\n      let posts = [];\n      let activeTag = \"\";\n      const selectedPostMatch = location.pathname.match(/^\\/post\\/(\\d+)\\/?$/);\n      const selectedPostDay = selectedPostMatch ? Number(selectedPostMatch[1]) : null;\n      if(selectedPostDay) archiveControls.hidden = true;\n\n      function node(tag, className, value){\n        const el = document.createElement(tag);\n        if(className) el.className = className;\n        if(value !== undefined && value !== null) el.textContent = String(value);\n        return el;\n      }\n      function makePost(post){\n        const card = node(\"article\",\"post\");\n        if(post.day !== undefined) card.id = \"post-\" + String(post.day);\n        const top = node(\"div\",\"post-top\");\n        top.append(node(\"span\",\"day\",\"CEO NOTES · DAY \" + post.day));\n        if(post.category) top.append(node(\"span\",\"post-category\",post.category));\n        if(post.publishedAt) top.append(node(\"time\",\"date\",post.publishedAt));\n        card.append(top);\n        if(post.imageUrl){\n          const image = document.createElement(\"img\");\n          image.src = post.imageUrl;\n          image.alt = \"صورة توضيحية: \" + (post.title || \"CEO Notes\");\n          image.loading = \"lazy\";\n          image.decoding = \"async\";\n          image.style.cssText = \"display:block;width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;margin:4px 0 16px;border:1px solid #c8a56855\";\n          card.append(image);\n        }\n        const heading = node(\"h3\",\"\");\n        const titleLink = node(\"a\",\"post-link\",post.title || \"ملاحظة يومية\");\n        titleLink.href = \"/post/\" + encodeURIComponent(String(post.day || \"\"));\n        heading.append(titleLink);\n        card.append(heading);\n        card.append(node(\"p\",\"article\",post.article || \"\"));\n        const detail = node(\"div\",\"detail\");\n        if(post.ideaOfTheDay){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"فكرة اليوم\"));\n          block.append(node(\"span\",\"\",post.ideaOfTheDay));\n          detail.append(block);\n        }\n        if(post.ceoChallenge){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"CEO CHALLENGE\"));\n          block.append(node(\"span\",\"\",post.ceoChallenge));\n          detail.append(block);\n        }\n        if(post.discussionQuestion){\n          const block = node(\"div\",\"detail-block\");\n          block.append(node(\"strong\",\"\",\"للنقاش\"));\n          block.append(node(\"span\",\"\",post.discussionQuestion));\n          detail.append(block);\n        }\n        const topicTags = Array.isArray(post.tags) ? post.tags : [];\n        if(topicTags.length){\n          const topicList = node(\"div\",\"topic-tags\");\n          topicTags.forEach(tag => topicList.append(node(\"span\",\"topic-tag\",tag)));\n          detail.append(topicList);\n        }\n        const tags = Array.isArray(post.hashtags) ? post.hashtags : String(post.hashtags || \"\").split(/\\s+/).filter(Boolean);\n        if(tags.length){\n          const tagList = node(\"div\",\"hashtags\");\n          tags.filter(Boolean).forEach(tag => tagList.append(node(\"span\",\"tag\",tag)));\n          detail.append(tagList);\n        }\n        card.append(detail);\n        const actions = node(\"div\",\"post-actions\");\n        const share = node(\"button\",\"share-button\",\"مشاركة المقال\");\n        share.type = \"button\";\n        share.addEventListener(\"click\",async()=>{\n          const shareUrl = location.origin + \"/post/\" + encodeURIComponent(String(post.day || \"\"));\n          const payload = {title:post.title || \"CEO Notes\",text:(post.title || \"CEO Notes\") + \" — CEO Notes\",url:shareUrl};\n          try{\n            if(navigator.share){await navigator.share(payload);}\n            else if(navigator.clipboard && navigator.clipboard.writeText){\n              await navigator.clipboard.writeText(shareUrl);\n              share.textContent = \"تم نسخ الرابط\";\n              share.setAttribute(\"aria-label\",\"تم نسخ رابط المقال\");\n            }else{\n              window.open(\"https://www.facebook.com/sharer/sharer.php?u=\" + encodeURIComponent(shareUrl),\"_blank\",\"noopener,noreferrer\");\n            }\n          }catch(error){\n            if(error && error.name !== \"AbortError\"){\n              share.textContent = \"تعذرت المشاركة\";\n            }\n          }\n        });\n        actions.append(share);\n        card.append(actions);\n        return card;\n      }\n      function renderFilters(){\n        const currentCategory = categoryFilter.value;\n        const categories = [...new Set(posts.map(post => post.category).filter(Boolean))]\n          .sort((a,b) => a.localeCompare(b,\"ar\"));\n        categoryFilter.replaceChildren(node(\"option\",\"\",\"كل الأقسام\"));\n        categories.forEach(category => {\n          const option = node(\"option\",\"\",category);\n          option.value = category;\n          categoryFilter.append(option);\n        });\n        categoryFilter.value = categories.includes(currentCategory) ? currentCategory : \"\";\n\n        const tags = [...new Set(posts.flatMap(post => Array.isArray(post.tags) ? post.tags : []))]\n          .filter(Boolean)\n          .sort((a,b) => a.localeCompare(b,\"ar\"));\n        tagFilters.replaceChildren();\n        const all = node(\"button\",\"tag-filter\",\"كل الوسوم\");\n        all.type = \"button\";\n        all.setAttribute(\"aria-pressed\",String(!activeTag));\n        all.addEventListener(\"click\",() => { activeTag = \"\"; renderFilters(); render(); });\n        tagFilters.append(all);\n        tags.forEach(tag => {\n          const button = node(\"button\",\"tag-filter\",tag);\n          button.type = \"button\";\n          button.setAttribute(\"aria-pressed\",String(activeTag === tag));\n          button.addEventListener(\"click\",() => { activeTag = tag; renderFilters(); render(); });\n          tagFilters.append(button);\n        });\n      }\n      function render(){\n        const q = search.value.trim().toLocaleLowerCase(\"ar\");\n        const selectedCategory = categoryFilter.value;\n        const filtered = posts.filter(post => {\n          if(selectedPostDay && Number(post.day) !== selectedPostDay) return false;\n          if(selectedCategory && post.category !== selectedCategory) return false;\n          const tags = Array.isArray(post.tags) ? post.tags : [];\n          if(activeTag && !tags.includes(activeTag)) return false;\n          const haystack = [post.day,post.title,post.article,post.ideaOfTheDay,post.ceoChallenge,post.discussionQuestion,post.category,post.tags,post.hashtags].join(\" \").toLocaleLowerCase(\"ar\");\n          return haystack.includes(q);\n        });\n        count.textContent = filtered.length + \" مقال منشور\";\n        list.replaceChildren();\n        if(!filtered.length){\n          const empty = node(\"div\",\"empty\");\n          empty.append(node(\"strong\",\"\",posts.length ? \"مفيش نتائج مطابقة\" : \"أول ملاحظة في الطريق\"));\n          empty.append(node(\"span\",\"\",posts.length ? \"جرّب كلمة بحث مختلفة.\" : \"المقالات ستظهر هنا تلقائيًا بعد اعتماد ونشر أول منشور.\"));\n          list.append(empty);\n          return;\n        }\n        filtered.forEach(post => list.append(makePost(post)));\n      }\n      search.addEventListener(\"input\",render);\n      categoryFilter.addEventListener(\"change\",render);\n      async function loadPosts(){\n        const fallbackUrl = (location.pathname.endsWith(\"/\") ? location.pathname : location.pathname + \"/\") + \"posts.json\";\n        let firstError = null;\n        for(const url of [\"/feed\",fallbackUrl]){\n          try{\n            const response = await fetch(url,{cache:\"no-store\",headers:{\"Accept\":\"application/json\"}});\n            if(!response.ok) throw new Error(\"HTTP \" + response.status);\n            const data = await response.json();\n            const items = Array.isArray(data) ? data : (Array.isArray(data.posts) ? data.posts : []);\n            if(!Array.isArray(items)) throw new Error(\"invalid_posts_format\");\n            posts = items.filter(item => item && item.status !== \"Draft\" && item.status !== \"Reserved\")\n              .sort((a,b) => Number(b.day || 0) - Number(a.day || 0));\n            renderFilters();\n            if(selectedPostDay){\n              const selected = posts.find(post => Number(post.day) === selectedPostDay);\n              if(selected){\n                document.title = (selected.title || \"CEO Notes\") + \" | CEO Notes\";\n                const description = String(selected.article || \"\").slice(0,155);\n                const descriptionMeta = document.querySelector('meta[name=\"description\"]');\n                if(descriptionMeta) descriptionMeta.content = description;\n                const canonical = document.querySelector('link[rel=\"canonical\"]');\n                if(canonical) canonical.href = location.origin + \"/post/\" + selectedPostDay;\n                const ogTitle = document.querySelector('meta[property=\"og:title\"]');\n                if(ogTitle) ogTitle.content = document.title;\n                const ogDescription = document.querySelector('meta[property=\"og:description\"]');\n                if(ogDescription) ogDescription.content = description;\n                const ogUrl = document.querySelector('meta[property=\"og:url\"]');\n                if(ogUrl) ogUrl.content = canonical ? canonical.href : location.href;\n                const imageUrl = typeof selected.imageUrl === \"string\" && selected.imageUrl.startsWith(\"https://\") ? selected.imageUrl : \"\";\n                const ogImage = document.querySelector('meta[property=\"og:image\"]');\n                if(ogImage) ogImage.content = imageUrl;\n                const twitterTitle = document.querySelector('meta[name=\"twitter:title\"]');\n                if(twitterTitle) twitterTitle.content = document.title;\n                const twitterDescription = document.querySelector('meta[name=\"twitter:description\"]');\n                if(twitterDescription) twitterDescription.content = description;\n                const twitterImage = document.querySelector('meta[name=\"twitter:image\"]');\n                if(twitterImage) twitterImage.content = imageUrl;\n                const twitterCard = document.querySelector('meta[name=\"twitter:card\"]');\n                if(twitterCard) twitterCard.content = imageUrl ? \"summary_large_image\" : \"summary\";\n              }\n            }\n            render();\n            return;\n          }catch(error){\n            if(!firstError) firstError = error;\n          }\n        }\n        list.replaceChildren();\n        const empty = node(\"div\",\"empty\");\n        empty.append(node(\"strong\",\"\",\"تعذر تحميل المقالات حاليًا\"));\n        empty.append(node(\"span\",\"\",\"حاول تحديث الصفحة بعد قليل.\"));\n        list.append(empty);\n        count.textContent = \"المحتوى غير متاح مؤقتًا\";\n      }\n      loadPosts();\n    })();\n  </script>\n<!-- CEO Notes live feed: Cloudflare Workers AI + KV -->\n  <script src=\"/radio.js\" defer></script>\n</body>\n</html>"
const POSTS="{\n  \"version\": 1,\n  \"posts\": [\n    {\n      \"day\": 1,\n      \"title\": \"أول خطأ يقع فيه معظم أصحاب الشركات هو أنهم يحاولون بيع المنتج قبل أن يفهموا سبب الشراء.\",\n      \"article\": \"العميل لا يستيقظ صباحًا وهو يبحث عن شركة تسويق، أو مكتب عقارات، أو تطبيق جديد.\\n\\nهو يبحث عن حل لمشكلة أو طريقة للوصول إلى نتيجة.\\n\\nلذلك قبل أن تسأل:\\n\\\"كيف أبيع؟\\\"\\n\\nاسأل:\\n\\\"ما المشكلة التي أجعلها تختفي؟\\\"\\n\\nكلما استطعت وصف مشكلة العميل بدقة، أصبح بيع الحل أسهل بكثير.\\n\\nجرب هذا التمرين مع أي مشروع:\\n\\n1. ما المشكلة التي أحلها؟\\n2. كم تكلف هذه المشكلة العميل إذا بقيت بدون حل؟\\n3. لماذا يعتبر حلي أفضل من البدائل؟\\n\\nإذا لم تستطع الإجابة على هذه الأسئلة في أقل من دقيقة، فالمشكلة ليست في التسويق... بل في وضوح الفكرة.\\n\\n💬 برأيك، ما أكبر خطأ تقع فيه الشركات عند محاولة بيع خدماتها؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #BusinessStrategy #Entrepreneurship #Marketing #Leadership #ArtificialIntelligence #BusinessGrowth #Startups #DecisionMaking #RoyalMindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-06T17:57:50.000Z\",\n      \"category\": \"التسويق والمبيعات\",\n      \"tags\": [\n        \"احتياجات العميل\",\n        \"القيمة\",\n        \"البيع\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_907116515742398\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1026260493322199/\",\n      \"sourcePublishedAt\": \"2026-07-06T17:57:50.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 2,\n      \"title\": \"لا تنافس على السعر... نافس على القيمة.\",\n      \"article\": \"أكبر خطأ ترتكبه الشركات هو الاعتقاد أن خفض السعر هو أسرع طريق لجذب العملاء.\\nلكن اسأل نفسك:\\nإذا كان العميل يختار الأرخص دائمًا... فلماذا توجد شركات أسعارها أعلى بمرتين أو ثلاث مرات وما زالت تحقق مبيعات قوية؟\\nالإجابة بسيطة:\\nالناس لا تدفع مقابل المنتج... بل مقابل القيمة التي تشعر أنها ستحصل عليها.\\nقبل أن تفكر في تخفيض السعر، اسأل نفسك:\\nهل أوضحت النتيجة التي سيحصل عليها العميل؟\\nهل شرحت لماذا أنت مختلف؟\\nهل جعلت قرار الشراء يبدو أقل مخاطرة؟\\nإذا كانت الإجابة \\\"لا\\\"، فالمشكلة ليست في السعر... بل في طريقة عرض القيمة.\\nالقاعدة الذهبية:\\nإذا اضطررت دائمًا للمنافسة بالسعر، فأنت لم تُظهر قيمة كافية.\\n💬 سؤال اليوم: هل سبق أن دفعت مبلغًا أكبر لأنك شعرت أن الجودة أو الثقة تستحق ذلك؟ ما السبب؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #Business #Leadership #Entrepreneurship #BusinessStrategy #Marketing #Branding #ArtificialIntelligence #AI #DecisionMaking #BusinessGrowth #SuccessMindset #Startups #RoyalEgyptGroup\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-07T11:25:48.000Z\",\n      \"category\": \"التسويق والمبيعات\",\n      \"tags\": [\n        \"القيمة\",\n        \"التسعير\",\n        \"المبيعات\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_907726042348112\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1003673482371187/\",\n      \"sourcePublishedAt\": \"2026-07-07T11:25:48.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 3,\n      \"title\": \"إذا لم تستطع شرح فكرتك في 30 ثانية... فأنت لا تفهمها بما يكفي.\",\n      \"article\": \"كثير من أصحاب الأعمال يعتقدون أن إضافة المزيد من التفاصيل تجعل فكرتهم أقوى.\\nلكن في الواقع يحدث العكس.\\nكلما احتاج العميل إلى وقت أطول ليفهم ما تقدمه، زادت احتمالية أن يفقد اهتمامه.\\nاسأل نفسك:\\nهل أستطيع أن أشرح عملي في جملة واحدة؟\\nإذا كانت الإجابة لا، فقد حان الوقت لإعادة تبسيط رسالتك.\\nجرب هذا التمرين:\\nأكمل الجملة التالية في أقل من 30 ثانية:\\n\\\"نساعد [من؟] على تحقيق [أي نتيجة؟] من خلال [كيف؟]\\\"\\nمثال:\\n\\\"نساعد الشركات الصغيرة على زيادة مبيعاتها من خلال استراتيجيات تسويق تعتمد على البيانات والذكاء الاصطناعي.\\\"\\nكلما كانت رسالتك أوضح، أصبح اتخاذ قرار التعامل معك أسهل.\\nالقاعدة الذهبية:\\nالتعقيد يثير الأسئلة... أما الوضوح فيبني الثقة.\\n💬 سؤال اليوم: لو طلب منك شخص أن تشرح عملك في 30 ثانية، ماذا ستقول؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #Business #Leadership #Entrepreneurship #BusinessStrategy #Marketing #Branding #ArtificialIntelligence #AI #DecisionMaking #BusinessGrowth #SuccessMindset #Startups #RoyalEgyptGroup\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-08T06:43:59.000Z\",\n      \"category\": \"التواصل والاستراتيجية\",\n      \"tags\": [\n        \"وضوح الفكرة\",\n        \"التواصل\",\n        \"الرسالة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_908442515609798\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1039025531981201/\",\n      \"sourcePublishedAt\": \"2026-07-08T06:43:59.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 4,\n      \"title\": \"الانشغال لا يعني الإنتاجية.\",\n      \"article\": \"من أكثر الأخطاء شيوعًا في عالم الأعمال أن يربط المدير بين كثرة المهام وكثرة الإنجاز.\\nلكن الحقيقة مختلفة.\\nيمكنك أن تعمل 12 ساعة يوميًا... وتحقق نتائج أقل من شخص عمل ساعتين فقط.\\nالفرق ليس في عدد الساعات... بل في اختيار المهمة الصحيحة.\\nقبل أن تبدأ يومك، اسأل نفسك:\\n\\\"ما المهمة الوحيدة التي إذا أنجزتها اليوم ستدفع عملي خطوة حقيقية إلى الأمام؟\\\"\\nابدأ بها أولًا.\\nاترك البريد الإلكتروني.\\nاترك الإشعارات.\\nواترك المهام التي تمنحك شعورًا زائفًا بالإنجاز.\\nالقاعدة الذهبية\\nلا تدِر وقتك... أدِر أولوياتك.\\nفإدارة الوقت تجعلك مشغولًا...\\nأما إدارة الأولويات فتصنع النتائج.\\n💬 سؤال اليوم:\\nما المهمة التي تؤجلها منذ فترة، رغم أنك تعلم أنها قد تُحدث أكبر فرق في عملك؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #الإدارة #ريادة_الأعمال #القيادة #إدارة_الوقت #الإنتاجية #التسويق #الذكاء_الاصطناعي #تطوير_الأعمال #بناء_الشركات #العمل_بذكاء #النجاح #Business #Leadership #WorkSmart\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-09T08:04:44.000Z\",\n      \"category\": \"الإدارة والإنتاجية\",\n      \"tags\": [\n        \"الإنتاجية\",\n        \"إدارة الأولويات\",\n        \"إدارة الوقت\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_909309135523136\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1497556714966840/\",\n      \"sourcePublishedAt\": \"2026-07-09T08:04:44.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 5,\n      \"title\": \"لا تبنِ شركة تعتمد عليك... ابنِ نظامًا يعمل بدونك.\",\n      \"article\": \"أحد أكبر الأخطاء التي يقع فيها رواد الأعمال هو الاعتقاد بأن نجاح الشركة يعني أن يكونوا موجودين في كل قرار، وكل اجتماع، وكل مهمة.\\nفي البداية قد يكون هذا ضروريًا...\\nلكن مع الوقت يتحول إلى أكبر عائق للنمو.\\nإذا توقفت الشركة عندما تأخذ إجازة...\\nفهذه ليست شركة.\\nإنها وظيفة صنعتها لنفسك.\\nالشركات القوية لا تعتمد على الأشخاص...\\nبل تعتمد على أنظمة واضحة، وإجراءات ثابتة، وفريق يعرف مسؤولياته.\\nاسأل نفسك اليوم:\\nهل يستطيع فريقي اتخاذ قرارات بدون الرجوع إليّ في كل مرة؟\\nهل كل مهمة لها طريقة عمل واضحة؟\\nهل أقضي وقتي في الإدارة... أم في إطفاء الحرائق؟\\n🏆 القاعدة الذهبية\\nالقائد الحقيقي لا يصنع نفسه بطلًا... بل يصنع فريقًا قادرًا على النجاح في غيابه.\\n💬 سؤال اليوم\\nلو اضطررت للابتعاد عن شركتك لمدة أسبوع كامل...\\nما أول شيء تتوقع أن يتوقف؟\\nإجابتك ستكشف لك أول نقطة تحتاج إلى تطويرها.\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #الإدارة #ريادة_الأعمال #القيادة #إدارة_الوقت #الإنتاجية #التسويق #الذكاء_الاصطناعي #تطوير_الأعمال #بناء_الشركات #العمل_بذكاء #النجاح #Business #Leadership #WorkSmart\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-10T07:46:01.000Z\",\n      \"category\": \"الإدارة وبناء الشركات\",\n      \"tags\": [\n        \"الأنظمة\",\n        \"الفريق\",\n        \"بناء الشركات\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_910099265444123\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/875488892286390/\",\n      \"sourcePublishedAt\": \"2026-07-10T07:46:01.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 6,\n      \"title\": \"ابنِ الثقة قبل أن تطلب البيع\",\n      \"article\": \"أكبر خطأ يقع فيه أغلب رواد الأعمال هو أنهم يحاولون البيع منذ أول دقيقة.\\n\\nالعميل لا يعرفك.\\nلا يثق بك.\\nولا يهمه كم تعبت في مشروعك.\\n\\nما يهمه فقط هو:\\nهل أنت الشخص المناسب لحل مشكلته؟\\n\\nالثقة تُبنى من خلال:\\n\\n- الالتزام بالمواعيد.\\n- الصدق حتى لو خسرت صفقة.\\n- عرض نتائج حقيقية.\\n- الرد السريع والاحترافي.\\n- تقديم قيمة قبل طلب المال.\\n\\nإذا نجحت في بناء الثقة...\\nسيصبح البيع مجرد خطوة أخيرة.\\n\\nCEO Mindset:\\n\\\"الثقة هي أغلى أصل تمتلكه أي شركة.\\\"\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEO #Leadership #Business #Entrepreneur #Sales #Marketing #Trust #RoyalEgypt #RealEstate #GrowthMindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-11T09:27:10.000Z\",\n      \"category\": \"التسويق وبناء الثقة\",\n      \"tags\": [\n        \"الثقة\",\n        \"العملاء\",\n        \"المبيعات\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_910963648691018\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1079993124557917/\",\n      \"sourcePublishedAt\": \"2026-07-11T09:27:10.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\",\n      \"sourceDuplicatePostIds\": [\n        \"115226621594988_910963648691018\",\n        \"115226621594988_911023832018333\"\n      ]\n    },\n    {\n      \"day\": 7,\n      \"title\": \"المدير التنفيذي لا يبحث عن القرار المثالي... بل عن القرار الصحيح في الوقت المناسب.\",\n      \"article\": \"من أكبر أسباب بطء الشركات أن أصحابها ينتظرون المعلومات الكاملة قبل اتخاذ أي قرار.\\nلكن في عالم الأعمال...\\nالوقت جزء من القرار.\\nأحيانًا يكون القرار الجيد اليوم... أفضل من القرار المثالي بعد شهر.\\nالرؤساء التنفيذيون الناجحون لا يسألون:\\n\\\"هل هذا القرار مضمون 100%؟\\\"\\nبل يسألون:\\n\\\"هل أملك معلومات كافية لاتخاذ القرار الآن؟\\\"\\nإذا كانت الإجابة نعم...\\nاتخذ القرار.\\nراقب النتائج.\\nثم عدّل المسار إذا لزم الأمر.\\nالتردد يستهلك الوقت... والوقت يستهلك الفرص.\\n🏆 القاعدة الذهبية\\nلا تنتظر اليقين الكامل...\\nاتخذ القرار بالمعلومات المتاحة، ثم حسّنه أثناء التنفيذ.\\n🎯 CEO Challenge\\nاختر قرارًا تؤجله منذ أكثر من أسبوع.\\nاسأل نفسك:\\nما أسوأ احتمال حقيقي؟\\nما أفضل نتيجة ممكنة؟\\nما أول خطوة يمكن تنفيذها اليوم؟\\nثم نفّذها قبل نهاية اليوم.\\n💬 سؤال اليوم\\nهل سبق أن أضعت فرصة بسبب كثرة التفكير؟\\n✍️\\nالقرارات لا تصنعها الشجاعة وحدها...\\nبل تصنعها سرعة التعلّم.\\nالمدير الناجح لا يخشى اتخاذ القرار...\\nبل يخشى أن يظل واقفًا بينما يتحرك الجميع.\\nلا تنتظر الكمال... ابدأ، ثم طوّر.\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #الإدارة #ريادة_الأعمال #اتخاذ_القرار #إدارة_الأعمال #بناء_الشركات #تطوير_الأعمال #العمل_بذكاء #النجاح #الإنتاجية #Leadership #BusinessStrategy #DecisionMaking #Entrepreneur #BusinessGrowth #WorkSmart #Management #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-12T16:35:36.000Z\",\n      \"category\": \"القيادة واتخاذ القرار\",\n      \"tags\": [\n        \"اتخاذ القرار\",\n        \"المعلومات\",\n        \"التوقيت\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_912007358586647\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1816324866443344/\",\n      \"sourcePublishedAt\": \"2026-07-12T16:35:36.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 8,\n      \"title\": \"لا تجعل الاجتماع هدفًا... اجعله وسيلة لاتخاذ قرار.\",\n      \"article\": \"كم مرة خرجت من اجتماع طويل...\\nثم اكتشفت أن شيئًا لم يتغير؟\\nالمشكلة ليست في الاجتماعات...\\nبل في الاجتماعات التي تنتهي بدون قرار، أو مسؤول، أو موعد تنفيذ.\\nالاجتماع الناجح يجب أن يجيب على ثلاثة أسئلة فقط:\\n✅ ما القرار الذي اتخذناه؟\\n✅ من المسؤول عن التنفيذ؟\\n✅ متى سيتم التنفيذ؟\\nإذا خرج الجميع دون إجابة واضحة على هذه الأسئلة...\\nفلم يكن اجتماعًا، بل كان مجرد نقاش.\\n🏆 القاعدة الذهبية\\nكل اجتماع يجب أن ينتهي بقرار... وليس بمحضر اجتماع فقط.\\n🎯 CEO Challenge\\nفي أول اجتماع لك هذا الأسبوع:\\nاكتب هدف الاجتماع في سطر واحد قبل أن يبدأ.\\nامنح كل بند وقتًا محددًا.\\nلا تغادر الاجتماع قبل تحديد المسؤول والموعد النهائي لكل مهمة.\\nراقب كيف ستختلف النتائج.\\n💬 سؤال اليوم\\nكم اجتماعًا حضرته وانتهى دون أي قرار حقيقي؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #الإدارة #ريادة_الأعمال #إدارة_الاجتماعات #اتخاذ_القرار #بناء_الشركات #تطوير_الأعمال #العمل_بذكاء #Leadership #BusinessStrategy #Management #DecisionMaking #Entrepreneur #BusinessGrowth #WorkSmart #Productivity #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-13T08:39:46.000Z\",\n      \"category\": \"إدارة الاجتماعات\",\n      \"tags\": [\n        \"الاجتماعات\",\n        \"القرارات\",\n        \"التنفيذ\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_912496201871096\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1508262373936812/\",\n      \"sourcePublishedAt\": \"2026-07-13T08:39:46.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 9,\n      \"title\": \"البيانات تتحدث... والآراء تُشتت.\",\n      \"article\": \"في عالم الأعمال، الآراء موجودة في كل مكان.\\nكل شخص لديه اقتراح. وكل شخص يعتقد أن فكرته هي الأفضل.\\nلكن المدير التنفيذي الناجح لا يبني قراراته على الانطباعات...\\nبل على البيانات.\\nقبل أن تغيّر استراتيجية التسويق... انظر إلى الأرقام.\\nقبل أن تطلق خدمة جديدة... ادرس احتياج السوق.\\nقبل أن تلوم فريق العمل... راجع مؤشرات الأداء.\\nالبيانات لا تمنع الخطأ...\\nلكنها تقلل احتمالية اتخاذ قرار خاطئ.\\n🏆 القاعدة الذهبية\\nإذا تعارضت الآراء مع البيانات... فابدأ بتحليل البيانات أولًا.\\n🎯 CEO Challenge\\nاختر قرارًا مهمًا تعمل عليه الآن.\\nثم اسأل نفسك:\\nما البيانات التي أستند إليها؟\\nهل هي حقائق أم مجرد توقعات؟\\nما الرقم الذي إذا تغيّر سيغيّر قراري؟\\nإذا لم تجد إجابة واضحة...\\nفأنت تحتاج إلى بيانات أكثر، لا إلى آراء أكثر.\\n💬 سؤال اليوم\\nهل سبق أن غيّرت رأيك بالكامل بعد أن رأيت الأرقام؟\\nCEONotes\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEO #القيادة #الإدارة #ريادة_الأعمال #البيانات #تحليل_البيانات #اتخاذ_القرار #بناء_الشركات #تطوير_الأعمال #العمل_بذكاء #Leadership #BusinessStrategy #DataDriven #DecisionMaking #Entrepreneur #BusinessGrowth #Management #WorkSmart #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-14T16:51:43.000Z\",\n      \"category\": \"البيانات واتخاذ القرار\",\n      \"tags\": [\n        \"البيانات\",\n        \"التحليل\",\n        \"الآراء\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_913601738427209\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/27408143385503770/\",\n      \"sourcePublishedAt\": \"2026-07-14T16:51:43.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\",\n      \"sourceNote\": \"رقم اليوم غير مكتوب في نص المنشور؛ أُسنِد إلى DAY9 وفق ترتيبه الزمني بين DAY8 وDAY10.\"\n    },\n    {\n      \"day\": 10,\n      \"title\": \"المشكلة التي تتكرر ليست مشكلة... بل نظام يحتاج إلى إصلاح.\",\n      \"article\": \"إذا كنت تحل نفس المشكلة كل أسبوع...\\nفأنت لا تعالج السبب الحقيقي.\\nالشركات الناجحة لا تقاس بسرعة حل المشكلات...\\nبل بقدرتها على منع تكرارها.\\nكل مشكلة متكررة هي رسالة تقول:\\n\\\"هناك عملية داخل الشركة تحتاج إلى تحسين.\\\"\\nبدل أن تسأل:\\n\\\"كيف أحل هذه المشكلة؟\\\"\\nاسأل:\\n\\\"كيف أمنع حدوثها مرة أخرى؟\\\"\\nهذا هو الفرق بين المدير الذي يدير يومه...\\nوالمدير التنفيذي الذي يبني شركة.\\n🏆 القاعدة الذهبية\\nلا تطفئ الحرائق كل يوم... ابنِ نظامًا يمنع اشتعالها من الأساس.\\n🎯 CEO Challenge\\nفكر في مشكلة تكررت داخل عملك خلال الشهر الماضي.\\nثم اكتب:\\n✅ لماذا حدثت؟\\n✅ ما السبب الحقيقي؟\\n✅ ما النظام الذي سيمنع تكرارها؟\\nابدأ بتنفيذ هذا النظام اليوم.\\n💬 سؤال اليوم\\nما أكثر مشكلة تتكرر في الشركات ويمكن حلها بوضع نظام\\n\\nواضح؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #بناء_الشركات #حل_المشكلات #تطوير_الأعمال #إدارة_العمليات #العمل_بذكاء #Leadership #BusinessStrategy #ProblemSolving #Systems #Management #Entrepreneur #BusinessGrowth #WorkSmart #Success #LeadershipMindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-16T16:58:20.000Z\",\n      \"category\": \"إدارة العمليات\",\n      \"tags\": [\n        \"حل المشكلات\",\n        \"العمليات\",\n        \"تحسين الأنظمة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_915280124926037\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1534294927920233/\",\n      \"sourcePublishedAt\": \"2026-07-16T16:58:20.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 11,\n      \"title\": \"لا تبحث عن عملاء أكثر... اصنع ثقة أكبر.\",\n      \"article\": \"يعتقد كثير من أصحاب الأعمال أن زيادة المبيعات تعني البحث عن عدد أكبر من العملاء.\\nلكن الحقيقة مختلفة.\\nالعملاء يشترون عندما يثقون.\\nوالثقة لا تُبنى بالكلام...\\nبل بالأفعال.\\nكل رسالة ترد عليها بسرعة.\\nكل وعد تلتزم به.\\nكل مشكلة تحلها باحترافية.\\nكل هذه التفاصيل الصغيرة تبني سمعة كبيرة.\\nقد ينسى العميل السعر...\\nلكنه لن ينسى كيف جعلته يشعر أثناء التعامل معك.\\n🏆 القاعدة الذهبية\\nالثقة هي العملة الحقيقية في عالم الأعمال.\\nكلما زادت الثقة...\\nأصبح البيع أسهل.\\n🎯 CEO Challenge\\nاليوم اسأل نفسك:\\nهل يثق العملاء في شركتي؟\\nما الدليل الحقيقي على ذلك؟\\nما خطوة واحدة أستطيع تنفيذها اليوم لزيادة ثقة العملاء؟\\nثم نفّذها قبل نهاية اليوم.\\n💬 سؤال اليوم\\nما أكثر صفة تجعلك تثق في شركة وتتعامل معها مرة أخرى؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #الثقة #خدمة_العملاء #المبيعات #بناء_الشركات #تطوير_الأعمال #العمل_بذكاء #Leadership #BusinessStrategy #CustomerExperience #Sales #Entrepreneur #BusinessGrowth #WorkSmart #Success #BrandBuilding\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-17T15:48:38.000Z\",\n      \"category\": \"تجربة العميل\",\n      \"tags\": [\n        \"الثقة\",\n        \"تجربة العميل\",\n        \"الاحتفاظ بالعملاء\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_916091468178236\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/4419087508326163/\",\n      \"sourcePublishedAt\": \"2026-07-17T15:48:38.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 12,\n      \"title\": \"لا تبيع المنتج... اجعل العميل يتخيل النتيجة.\",\n      \"article\": \"العميل لا يستيقظ صباحًا وهو يريد شراء منتجك...\\nبل يستيقظ لأنه يريد حل مشكلة، أو تحقيق هدف، أو الوصول إلى شعور معين.\\nلا أحد يشتري شقة لأنه يريد أربعة جدران...\\nبل لأنه يبحث عن الاستقرار، الأمان، والاستثمار.\\nولا أحد يشتري خدمة تسويق لأنه يريد إعلانًا...\\nبل لأنه يريد عملاء أكثر ونموًا أكبر.\\nالمدير التنفيذي الذكي لا يتحدث عن مواصفات المنتج أولًا...\\nبل يتحدث عن النتيجة التي سيعيشها العميل بعد الشراء.\\nاسأل نفسك دائمًا:\\nهل أبيع منتجًا... أم أبيع مستقبلًا أفضل للعميل؟\\n🏆 القاعدة الذهبية\\nالناس لا تشتري ما تبيع... بل تشتري ما سيصبحون عليه بعد الشراء.\\n🎯 CEO Challenge\\nاختر منتجًا أو خدمة تقدمها.\\nثم اكتب:\\n❌ ما هي المواصفات؟\\n✅ ما النتيجة التي سيحصل عليها العميل؟\\n✅ كيف ستتغير حياته أو عمله بعد الشراء؟\\nإذا ركزت على النتيجة...\\nستجد أن رسالتك التسويقية أصبحت أقوى.\\n💬 سؤال اليوم\\nعندما تشتري أي منتج... ما الذي يؤثر في قرارك أكثر؟\\nالسعر؟\\nالجودة؟\\n\\nأم النتيجة التي تتوقعها؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #التسويق #المبيعات #بناء_العلامة_التجارية #العمل_بذكاء #تطوير_الأعمال #خدمة_العملاء #Leadership #BusinessStrategy #Marketing #Sales #Branding #CustomerExperience #Entrepreneur #BusinessGrowth #WorkSmart #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-18T07:19:56.000Z\",\n      \"category\": \"التسويق وقيمة العميل\",\n      \"tags\": [\n        \"قيمة العميل\",\n        \"النتائج\",\n        \"التجربة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_916602178127165\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/2100245827559960/\",\n      \"sourcePublishedAt\": \"2026-07-18T07:19:56.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 13,\n      \"title\": \"العلامة التجارية ليست ما تقوله عن نفسك... بل ما يقوله الناس عنك.\",\n      \"article\": \"الكثير من الشركات تركز على تصميم شعار جميل، أو إعلان قوي، أو كلمات تسويقية جذابة...\\nلكن العلامة التجارية الحقيقية لا تُبنى بالكلام فقط.\\nهي تُبنى من كل تجربة يمر بها العميل معك.\\nمن أول رسالة.\\nمن سرعة الرد.\\nمن جودة الخدمة.\\nمن طريقة التعامل عند حدوث مشكلة.\\nالعميل لا يتذكر فقط ما بعته له...\\nبل يتذكر كيف جعلته يشعر.\\nالشركات القوية لا تسأل:\\n\\\"كيف نظهر بشكل أفضل؟\\\"\\nبل تسأل:\\n\\\"كيف نصبح أفضل فعلًا؟\\\"\\nلأن الصورة التي يصنعها الناس عن شركتك هي أقوى إعلان يمكن أن تحصل عليه.\\n🏆 القاعدة الذهبية\\nسمعتك هي العلامة التجارية التي لا يمكنك شراؤها بالإعلانات.\\n🎯 CEO Challenge\\nاليوم اسأل نفسك:\\nماذا سيقول العميل عن شركتي لو سألته الآن؟\\nهل التجربة التي أقدمها تطابق الصورة التي أريدها؟\\nما الشيء الصغير الذي يمكن تحسينه اليوم؟\\n💬 سؤال اليوم\\nما الشركة التي تثق بها بسبب تجربتك معها وليس بسبب إعلاناتها؟ ولماذا؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #العلامة_التجارية #Branding #CustomerExperience #بناء_الثقة #خدمة_العملاء #تطوير_الأعمال #التسويق #الإدارة #العمل_بذكاء #Leadership #BusinessStrategy #Entrepreneur #BusinessGrowth #WorkSmart #Success #BrandValue\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-22T06:38:31.000Z\",\n      \"category\": \"العلامة التجارية\",\n      \"tags\": [\n        \"السمعة\",\n        \"الهوية\",\n        \"الثقة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_919781057809277\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1320456593578312/\",\n      \"sourcePublishedAt\": \"2026-07-22T06:38:31.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 14,\n      \"title\": \"لا تنافس على السعر... اجعل المقارنة مستحيلة.\",\n      \"article\": \"أكبر خطأ يقع فيه كثير من أصحاب الأعمال هو الدخول في حرب أسعار.\\nاليوم تخفض السعر...\\nوغدًا يخفضه المنافس أكثر.\\nوفي النهاية يخسر الجميع.\\nالشركات القوية لا تبني ميزتها على أنها الأرخص...\\nبل على أنها الأكثر قيمة.\\nاسأل نفسك:\\nلماذا يختارك العميل أنت؟\\nإذا كانت الإجابة هي السعر فقط...\\nفسيتركك بمجرد أن يجد سعرًا أقل.\\nأما إذا كانت الإجابة:\\nثقة.\\nجودة.\\nسرعة.\\nخدمة.\\nخبرة.\\nتجربة استثنائية.\\nفأنت لا تنافس على السعر...\\nبل تنافس على القيمة.\\nوهنا تصبح المقارنة مع الآخرين شبه مستحيلة.\\n🏆 القاعدة الذهبية\\nإذا اضطر العميل للمقارنة بالسعر... فأنت لم توضح قيمة ما تقدمه بما يكفي.\\n🎯 CEO Challenge\\nاكتب اليوم ثلاثة أسباب تجعل العميل يختارك حتى لو كنت أغلى من المنافس.\\nإذا لم تجد ثلاثة أسباب واضحة...\\nفابدأ في بنائها من اليوم.\\n💬 سؤال اليوم\\nهل تفضل دائمًا الأرخص... أم الأفضل قيمة؟ ولماذا؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #التسويق #المبيعات #القيمة #العلامة_التجارية #الإدارة #العمل_بذكاء #تطوير_الأعمال #Leadership #BusinessStrategy #Marketing #Sales #Value #Entrepreneur #BusinessGrowth #WorkSmart #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-23T06:20:22.000Z\",\n      \"category\": \"التسويق والتميّز\",\n      \"tags\": [\n        \"القيمة\",\n        \"التميّز\",\n        \"التسعير\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_920574781063238\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/2650005472097862/\",\n      \"sourcePublishedAt\": \"2026-07-23T06:20:22.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 15,\n      \"title\": \"لا تبيع مرة واحدة... ابنِ عميلاً يعود إليك دائمًا.\",\n      \"article\": \"كثير من الشركات تعتبر أن عملية البيع تنتهي بمجرد استلام العميل للمنتج أو الخدمة.\\nلكن الحقيقة...\\nالبيع الحقيقي يبدأ بعد أول عملية شراء.\\nالعميل الراضي لا يمنحك عملية بيع واحدة فقط...\\nبل يمنحك:\\nعملية شراء جديدة.\\nتوصية لأصدقائه.\\nثقة تدوم لسنوات.\\nتكلفة الاحتفاظ بعميل حالي غالبًا أقل من تكلفة الحصول على عميل جديد.\\nلذلك، الشركات الذكية لا تسأل:\\n\\\"كم عميل جديد حصلنا عليه؟\\\"\\nبل تسأل:\\n\\\"كم عميل عاد إلينا مرة أخرى؟\\\"\\nالعلاقة طويلة المدى هي الاستثمار الحقيقي.\\n🏆 القاعدة الذهبية\\nالبيع الناجح لا ينتهي بالفاتورة... بل يبدأ منها.\\n🎯 CEO Challenge\\nاختر آخر 10 عملاء تعاملوا معك.\\nثم اسأل نفسك:\\nكم واحد منهم عاد للشراء مرة أخرى؟\\nهل تواصلت معهم بعد البيع؟\\nما الذي يمكنك فعله ليصبحوا عملاء دائمين؟\\nضع خطة بسيطة لمتابعة العملاء بعد البيع خلال هذا الأسبوع.\\n💬 سؤال اليوم\\nما الذي يجعلك تعود للتعامل مع نفس الشركة مرة أخرى؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #المبيعات #خدمة_العملاء #CustomerExperience #CustomerRetention #بناء_العلامة_التجارية #تطوير_الأعمال #الإدارة #العمل_بذكاء #Leadership #BusinessStrategy #Sales #BusinessGrowth #Entrepreneur #WorkSmart #Success #CustomerSuccess\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-24T09:09:30.000Z\",\n      \"category\": \"العلاقات مع العملاء\",\n      \"tags\": [\n        \"ولاء العملاء\",\n        \"الاحتفاظ بالعملاء\",\n        \"خدمة العملاء\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_921484160972300\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1364807975791629/\",\n      \"sourcePublishedAt\": \"2026-07-24T09:09:30.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 16,\n      \"title\": \"إذا لم تستطع قياسه... فلن تستطيع تطويره.\",\n      \"article\": \"كثير من الشركات تعمل بجد...\\nلكنها لا تعرف إن كانت تتحسن أم لا.\\nالسبب بسيط:\\nلا توجد مؤشرات أداء واضحة.\\nلا يكفي أن تقول:\\n\\\"المبيعات جيدة.\\\"\\nاسأل:\\nكم عدد العملاء الجدد هذا الشهر؟\\nكم نسبة تحويل العملاء المحتملين إلى مشترين؟\\nكم متوسط وقت الرد على العميل؟\\nكم عميل عاد للشراء مرة أخرى؟\\nالأرقام تحول العمل من التخمين...\\nإلى الإدارة الواعية.\\nالمدير التنفيذي الناجح لا يراقب كل شيء...\\nبل يراقب المؤشرات التي تصنع النتائج.\\n🏆 القاعدة الذهبية\\nما لا يُقاس... لا يُدار، وما لا يُدار... لا يتطور.\\n🎯 CEO Challenge\\nاختر 5 مؤشرات أداء (KPIs) لشركتك، مثل:\\n✅ عدد العملاء الجدد.\\n✅ نسبة إتمام المبيعات.\\n✅ رضا العملاء.\\n✅ سرعة الرد.\\n✅ الإيرادات الشهرية.\\nثم راقبها أسبوعيًا لمدة شهر، ولاحظ كيف ستتغير جودة قراراتك.\\n💬 سؤال اليوم\\nما أهم رقم تتابعه في عملك باستمرار؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #KPIs #تحليل_البيانات #اتخاذ_القرار #تطوير_الأعمال #العمل_بذكاء #Leadership #BusinessStrategy #Management #DataDriven #BusinessGrowth #Entrepreneur #Productivity #WorkSmart #Success #PerformanceMetrics\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-25T04:29:30.000Z\",\n      \"category\": \"الأداء والقياس\",\n      \"tags\": [\n        \"مؤشرات الأداء\",\n        \"القياس\",\n        \"التطوير\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_922144887572894\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1554371286064994/\",\n      \"sourcePublishedAt\": \"2026-07-25T04:29:30.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 17,\n      \"title\": \"الوقت هو رأس المال الوحيد الذي لا يمكن استعادته.\",\n      \"article\": \"يمكنك أن تخسر مالًا ثم تعوضه...\\nيمكنك أن تخسر صفقة ثم تربح غيرها...\\nلكن الدقيقة التي مضت...\\nلن تعود أبدًا.\\nلهذا السبب لا يسأل المدير التنفيذي الناجح:\\n\\\"كم ساعة عملت اليوم؟\\\"\\nبل يسأل:\\n\\\"هل قضيت وقتي في أهم الأعمال؟\\\"\\nهناك فرق كبير بين:\\nأن تكون مشغولًا.\\nوأن تكون منتجًا.\\nقد تعمل 12 ساعة دون إنجاز حقيقي...\\nوقد تعمل 3 ساعات فقط وتحقق نتائج تغيّر مستقبل شركتك.\\nإدارة الوقت ليست ملء جدولك... بل حماية وقتك من كل ما لا يضيف قيمة.\\n🏆 القاعدة الذهبية\\nلا تُدِر وقتك... أدِر أولوياتك، وسيُدار وقتك تلقائيًا.\\n🎯 CEO Challenge\\nقبل أن تبدأ يومك غدًا، اكتب:\\n✅ أهم 3 مهام فقط.\\nولا تنتقل إلى أي مهمة أخرى حتى تنتهي منها.\\nثم راقب الفرق في إنتاجيتك.\\n💬 سؤال اليوم\\nما أكثر شيء يسرق وقتك أثناء العمل؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #إدارة_الوقت #الإنتاجية #العمل_بذكاء #الإدارة #تطوير_الأعمال #Leadership #BusinessStrategy #Productivity #TimeManagement #Entrepreneur #BusinessGrowth #Focus #WorkSmart #Success #LeadershipMindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-07-28T08:04:35.000Z\",\n      \"category\": \"إدارة الوقت\",\n      \"tags\": [\n        \"إدارة الوقت\",\n        \"الأولويات\",\n        \"التركيز\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_924744337312949\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1519250226152328/\",\n      \"sourcePublishedAt\": \"2026-07-28T08:04:35.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 18,\n      \"title\": \"الغياب مش دائمًا تأخير... أحيانًا هو جزء من الاستراتيجية.\",\n      \"article\": \"أحد أخطر الأخطاء في عالم الأعمال... أنك تعتقد أن الحركة تعني التقدم.\\n\\nومش كل قرار لازم يتخذ فورًا.\\nومش كل فرصة لازم تقتنصها.\\nومش كل اجتماع لازم يتم.\\nومش كل يوم لازم تنشر.\\n\\nأحيانًا...\\nأذكى حركة ممكن تعملها هي أن تتوقف قليلًا.\\nتراقب • تراجع • تسأل نفسك:\\nهل أنا ما زلت أسير في الاتجاه الصحيح؟\\n\\nالتوقف للمراجعة ليس تعطيلًا للعمل...\\nبل حماية للعمل من أن يكبر في الاتجاه الخطأ.\\n\\nCEO RULE\\nليس المهم أن تتحرك دائمًا...\\nالمهم أن تعرف لماذا تتحرك.\\n\\nتحدي اليوم\\nخذ قرارًا واحدًا كنت تؤجله أو تتعامل معه بشكل تلقائي.\\nولا تسأل: «كيف أنفذه؟»\\nاسأل أولًا: «هل يستحق التنفيذ أصلًا؟»\\nهذا السؤال وحده... قد يوفر عليك شهورًا من العمل.\\n\\nوالعودة الحقيقية؟\\nمش إننا نقول: «رجعنا.»\\nالعودة الحقيقية إننا نرجع أذكى من المرة اللي فاتت.\\nومن هنا...\\nCEO Notes تعود من جديد.\\nليس بعدد أكبر من النصائح...\\nبل بأسئلة أصعب، وأفكار أعمق، وأشياء عملية\\nتخليك تفكر في شغلك بطريقة مختلفة.\",\n      \"ideaOfTheDay\": \"التوقف للمراجعة ليس تعطيلًا للعمل، بل حماية للعمل من أن يكبر في الاتجاه الخطأ.\",\n      \"ceoChallenge\": \"خذ قرارًا واحدًا كنت تؤجله أو تتعامل معه بشكل تلقائي. بدل أن تسأل «كيف أنفذه؟»، اسأل أولًا «هل يستحق التنفيذ أصلًا؟».\",\n      \"discussionQuestion\": \"هل أنا ما زلت أسير في الاتجاه الصحيح؟\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #الإدارة #التفكير_الاستراتيجي\",\n      \"status\": \"Published\",\n      \"category\": \"القيادة والتخطيط\",\n      \"tags\": [\n        \"المراجعة الاستراتيجية\",\n        \"تحديد الاتجاه\",\n        \"التوقف الواعي\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": null,\n      \"sourceUrl\": null,\n      \"sourcePublishedAt\": null,\n      \"sourceEvidence\": \"saved_day18_artwork\",\n      \"sourceAsset\": \"CEO Comeback: A Smarter Return.png\",\n      \"sourceAssetCreatedAt\": \"2026-08-09T00:49:43.675365Z\",\n      \"sourceNote\": \"استعادة تحريرية من صورة DAY18 الأصلية المحفوظة في المكتبة؛ لم يظهر سجل المنشور النصي في نتيجة قائمة منشورات فيسبوك.\"\n    },\n    {\n      \"day\": 19,\n      \"title\": \"أخطر كلمة في البيزنس: «نعم»\",\n      \"article\": \"كل فرصة تقول لها نعم...\\nأنت في الحقيقة بتقول لا لفرصة أخرى.\\nنعم لاجتماع إضافي = لا لساعة تركيز.\\nنعم لعميل غير مناسب = لا لوقت يمكن أن تستثمره في عميل أفضل.\\nنعم لمشروع جديد = لا لمشروعك الأساسي.\\nنعم لكل طلب من الفريق = لا لوقتك كقائد.\\nالمشكلة إن كلمة \\\"نعم\\\" تبدو إيجابية دائمًا.\\nلكن المدير التنفيذي لا يقيس قراراته بعدد الأشياء التي وافق عليها...\\nبل بعدد الأشياء المهمة التي حافظ عليها من التشتيت.\\n🧠 CEO RULE\\nكل \\\"نعم\\\" لها تكلفة مخفية.\\nاسأل عن التكلفة قبل أن تسأل عن الفائدة.\\n🎯 تحدي اليوم\\nقبل ما توافق على أي شيء جديد اليوم، اسأل 3 أسئلة:\\n1. هل هذا يخدم هدفي الأساسي؟\\n2. ماذا سأضطر إلى تأجيله لو وافقت؟\\n3. ماذا سيحدث لو قلت \\\"لا\\\"؟\\nلو كانت الإجابة مش واضحة...\\n\\nلا تستعجل الموافقة.\\n💬 سؤال اليوم\\nما الشيء الذي وافقت عليه من قبل، ثم اكتشفت أنه كان يستحق كلمة \\\"لا\\\"؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #اتخاذ_القرار #التركيز #العمل_بذكاء #التفكير_الاستراتيجي #تطوير_الأعمال #BusinessMindset #Leadership #BusinessStrategy #DecisionMaking #Focus #Entrepreneurship #WorkSmart #BusinessGrowth\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-08-10T02:57:17.000Z\",\n      \"category\": \"التركيز الاستراتيجي\",\n      \"tags\": [\n        \"التركيز\",\n        \"اتخاذ القرار\",\n        \"إدارة الفرص\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_935861952867854\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1056836680643235/\",\n      \"sourcePublishedAt\": \"2026-08-10T02:57:17.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 20,\n      \"title\": \"أغلى شيء في شركتك قد يكون الشيء الذي لا تراه.\",\n      \"article\": \"أحيانًا صاحب الشركة يفتكر إن أكبر خسارة هي:\\nصفقة ضاعت.\\nعميل مشي.\\nإعلان فشل.\\nموظف استقال.\\nلكن في خسارة أخطر...\\nالوقت الذي يضيع بدون أن يظهر في الحسابات.\\nموظف ينتظر موافقة 3 أيام.\\nمدير يعيد نفس الشرح كل أسبوع.\\nاجتماع مدته ساعتان كان ممكن يتحسم في 15 دقيقة.\\nعميل ينتظر ردًا لأن لا أحد يعرف من المسؤول.\\nمعلومة موجودة عند شخص واحد فقط.\\nكل واحدة من هذه الأشياء تبدو صغيرة.\\nلكن لما تتكرر يوميًا...\\nالشركة كلها تبدأ تدفع ثمنها.\\nوهنا سؤال الـ CEO الحقيقي:\\nأين يختفي الوقت داخل شركتي؟\\nمش:\\n\\\"مين مشغول؟\\\"\\nلكن:\\n\\\"فين الوقت بيتسرّب؟\\\"\\n🧠 CEO RULE\\nالمشكلة ليست دائمًا في الأشخاص... أحيانًا المشكلة في الطريقة التي صُمم بها العمل.\\nلو موظف ممتاز يحتاج 5 خطوات للحصول على موافقة بسيطة...\\nلا تلوم الموظف.\\nراجع النظام.\\n🎯 CEO CHALLENGE\\nاليوم راقب شركتك لمدة ساعة واحدة فقط.\\nوأي وقت تلاحظ فيه:\\nانتظار ❌\\nتكرار ❌\\nموافقة غير ضرورية ❌\\nمعلومة ناقصة ❌\\nاجتماع بلا نتيجة ❌\\nاكتبه.\\nثم اسأل:\\n\\\"لو ألغيت هذه الخطوة... ماذا سيحدث؟\\\"\\nقد تكتشف أن أكبر فرصة لتطوير شركتك...\\nليست في إضافة شيء جديد، بل في حذف شيء قديم.\\n💬 سؤال اليوم\\nما الشيء الذي يستهلك وقتًا داخل الشركات، لكنه أصبح طبيعيًا لدرجة أن الجميع توقف عن ملاحظته؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #العمل_بذكاء #إدارة_الوقت #الإنتاجية #تطوير_الأعمال #التفكير_الاستراتيجي #BusinessMindset #Leadership #BusinessStrategy #Productivity #TimeManagement #Entrepreneurship #BusinessGrowth #WorkSmart #Efficiency #Success\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-08-11T11:25:14.000Z\",\n      \"category\": \"كفاءة العمليات\",\n      \"tags\": [\n        \"إدارة الوقت\",\n        \"كفاءة العمليات\",\n        \"الإنتاجية\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_936985349422181\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1042063078582889/\",\n      \"sourcePublishedAt\": \"2026-08-11T11:25:14.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 21,\n      \"title\": \"أحيانًا أفضل موظف عندك... هو المشكلة التي اكتشفتها مبكرًا.\",\n      \"article\": \"في الإدارة، أغلب الناس بتتعامل مع المشكلة كأنها عدو.\\nلكن الـ CEO الذكي ينظر لها بشكل مختلف.\\nالمشكلة التي تظهر أمامك اليوم... قد تكون فرصة لإنقاذ الشركة من مشكلة أكبر غدًا.\\nعميل اشتكى؟\\nممتاز.\\nلأنك عرفت أين يوجد الخلل.\\nموظف قال إن النظام معقد؟\\nممتاز.\\nلأنك اكتشفت نقطة تعطّل.\\nصفقة ضاعت بسبب إجراء معين؟\\nمؤلم...\\nلكنها كشفت لك شيئًا كان ممكن يكلفك عشرات الصفقات لاحقًا.\\nالمشكلة ليست دائمًا خسارة.\\nأحيانًا المشكلة هي أرخص إنذار تحصل عليه قبل الكارثة.\\nوهنا عقلية الـ CEO:\\nبدل:\\n\\\"مين السبب؟\\\"\\nاسأل:\\n\\\"إيه اللي النظام سمح بحدوثه؟\\\"\\nلأنك لو عاقبت الشخص فقط...\\nقد تختفي المشكلة مؤقتًا.\\nلكن لو أصلحت النظام...\\nالمشكلة قد لا تعود أصلًا.\\n🧠 CEO RULE\\nلا تعاقب أول شخص اكتشف المشكلة... اشكره، ثم أصلح السبب.\\n🎯 CEO CHALLENGE\\nخذ أكبر شكوى أو خطأ حدث عندك مؤخرًا.\\nولا تبحث عن الشخص المخطئ.\\nابحث عن:\\nما الخطوة التي كان يمكن تغييرها لمنع الخطأ من الأساس؟\\nلو وجدت الإجابة...\\nفأنت لم تحل مشكلة.\\nأنت طورت الشركة.\\n💬 سؤال اليوم\\nلو كان بإمكانك اكتشاف مشكلة واحدة داخل أي شركة قبل أن تتحول إلى أزمة... ماذا ستختار؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #حل_المشكلات #التفكير_الاستراتيجي #تطوير_الأعمال #العمل_بذكاء #إدارة_العمليات #Leadership #BusinessMindset #BusinessStrategy #ProblemSolving #Entrepreneurship #BusinessGrowth #WorkSmart #Management #Success #CEOmindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-08-12T19:12:59.000Z\",\n      \"category\": \"التعلم وتحسين الأنظمة\",\n      \"tags\": [\n        \"حل المشكلات\",\n        \"الإنذار المبكر\",\n        \"تحسين الأنظمة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_938190712634978\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1023842863604561/\",\n      \"sourcePublishedAt\": \"2026-08-12T19:12:59.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 22,\n      \"title\": \"لو كل حاجة في شركتك لازم تعدّي عليك... فأنت مش بتدير شركة. أنت أصبحت عنق الزجاجة.\",\n      \"article\": \"في البداية، طبيعي إن صاحب المشروع يعمل كل حاجة.\\n\\nيرد على العملاء.\\nيراجع الحسابات.\\nيتابع الموظفين.\\nيحل المشاكل.\\nيوافق على القرارات.\\n\\nلكن هناك لحظة خطيرة جدًا...\\n\\nالشركة تكبر، وصاحبها لا يتغير.\\n\\nفتصبح كل حاجة محتاجة:\\n\\n\\\"اسأل المدير.\\\"\\n\\n\\\"استنى موافقة المدير.\\\"\\n\\n\\\"خليه يشوف.\\\"\\n\\n\\\"المدير يقرر.\\\"\\n\\nوهنا تحصل المفارقة:\\n\\nكلما نجحت الشركة أكثر...\\n\\nأصبحت أبطأ.\\n\\nمش لأن الفريق ضعيف.\\n\\nلكن لأن كل القرارات تمر من نقطة واحدة:\\n\\nأنت.\\n\\n---\\n\\n🧠 CEO RULE\\n\\nهدفك ليس أن تصبح الشخص الذي لا يمكن الاستغناء عنه.\\n\\nهدفك أن تبني شركة تستطيع أن تعمل بكفاءة...\\n\\nحتى عندما لا تكون موجودًا.\\n\\nالقائد الحقيقي لا يبني فريقًا يحتاجه في كل تفصيلة.\\n\\nبل يبني:\\n\\nأشخاصًا + أنظمة + صلاحيات + معايير واضحة.\\n\\n---\\n\\n🎯 CEO CHALLENGE\\n\\nاختار اليوم 3 قرارات يتكرر رجوع الفريق إليك فيها.\\n\\nواسأل نفسك:\\n\\n«\\\"لماذا ما زال هذا القرار يحتاجني؟\\\"»\\n\\nهل السبب:\\n\\n- لا توجد صلاحية واضحة؟\\n- لا يوجد نظام؟\\n- لا توجد قاعدة لاتخاذ القرار؟\\n- أم أنني ببساطة لا أثق في التفويض؟\\n\\nثم اختر قرارًا واحدًا...\\n\\nوفوّضه بالكامل.\\n\\nمش \\\"فوّضه وراجع كل خطوة\\\".\\n\\nفوّض النتيجة.\\n\\n---\\n\\n💡 الفكرة التي لا ينتبه لها أحد\\n\\nأحيانًا أكبر دليل على نجاح المدير...\\n\\nليس أن الموظفين يقولون:\\n\\n\\\"مفيش حاجة بتحصل غير لما المدير يوافق.\\\"\\n\\nبل العكس تمامًا:\\n\\n\\\"كل حاجة ماشية... حتى والمدير مش موجود.\\\"\\n\\n---\\n\\n💬 سؤال اليوم\\n\\nلو اختفيت من شركتك لمدة 30 يومًا... إيه أول حاجة هتتوقف؟\\n\\nالإجابة دي ممكن تكشف لك أهم شيء تحتاج إلى بنائه الآن.\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #القيادة #ريادة_الأعمال #الإدارة #التفويض #بناء_الفريق #بناء_الشركات #العمل_بذكاء #التفكير_الاستراتيجي #تطوير_الأعمال #Leadership #BusinessMindset #Delegation #BusinessStrategy #Entrepreneurship #BusinessGrowth #WorkSmart #Management #CEOmindset\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-08-16T10:27:00.000Z\",\n      \"category\": \"القيادة والتفويض\",\n      \"tags\": [\n        \"التفويض\",\n        \"بناء الفريق\",\n        \"الصلاحيات\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_941305458990170\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/810873318763114/\",\n      \"sourcePublishedAt\": \"2026-08-16T10:27:00.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 23,\n      \"title\": \"أخطر قرار ممكن تاخده في شركتك... هو القرار الذي لم تتخذه.\",\n      \"article\": \"في ناس بتخاف من القرار الغلط.\\nفتؤجل.\\nتجمع معلومات أكثر.\\nتنتظر التوقيت المثالي.\\nتستنى رأي شخص آخر.\\nثم يمر أسبوع...\\nوشهر...\\nوالفرصة تختفي.\\nالحقيقة اللي مش ناس كتير بتتكلم عنها:\\nعدم اتخاذ القرار هو قرار بحد ذاته.\\nلما تتأخر في تعيين شخص مناسب، أنت اخترت أن تتحمل ضغط العمل الحالي.\\nلما تتأخر في تغيير طريقة فاشلة، أنت اخترت استمرار الخسارة.\\nلما تتأخر في استغلال فرصة، أنت أعطيت منافسك فرصة يتحرك قبلك.\\n🧠 CEO RULE\\nمش مطلوب منك تعرف كل الإجابات قبل ما تتحرك.\\nمطلوب تعرف إمتى عندك معلومات كافية لاتخاذ القرار.\\nالـ CEO الذكي لا يبحث عن:\\n100% يقين.\\nلأنه غالبًا غير موجود.\\nهو يبحث عن:\\nمعلومة كافية + مخاطرة محسوبة + سرعة تنفيذ.\\n🎯 CEO CHALLENGE\\nفكر في قرار واحد مأجله من فترة.\\nواكتب أمامه:\\nما أسوأ شيء يمكن أن يحدث لو أخذت القرار؟\\nثم:\\nما أسوأ شيء يمكن أن يحدث لو لم آخذه؟\\nأحيانًا...\\nهتكتشف إن عدم التحرك أخطر من التحرك.\\n💡 فكرة اليوم\\nالقرار الجيد في الوقت المناسب\\nأفضل من القرار المثالي بعد فوات الأوان.\\n💬 سؤال اليوم\\nهل أنت بتأجل قرارًا مهمًا لأنك تحتاج معلومات أكثر... أم لأنك تخاف من النتيجة؟\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #CEOMindset #القيادة #ريادة_الأعمال #اتخاذ_القرار #التفكير_الاستراتيجي #الإدارة #تطوير_الأعمال #العمل_بذكاء #BusinessMindset #Leadership #DecisionMaking #BusinessStrategy #Entrepreneurship #BusinessGrowth #WorkSmart #Management #Success #StrategicThinking\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-08-18T18:24:23.000Z\",\n      \"category\": \"القيادة واتخاذ القرار\",\n      \"tags\": [\n        \"اتخاذ القرار\",\n        \"التوقيت\",\n        \"المخاطرة المحسوبة\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_943320672121982\",\n      \"sourceUrl\": \"https://www.facebook.com/reel/1582452686716422/\",\n      \"sourcePublishedAt\": \"2026-08-18T18:24:23.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 24,\n      \"title\": \"كنت بفكر أشتغل تاجر مخدرات... وبعدين فهمت البيزنس.\",\n      \"article\": \"آه... العنوان غريب.\\n\\nبس استنى.\\n\\nأنا مش هتكلم عن المخدرات.\\n\\nهتكلم عن الإدمان.\\n\\nلأن لما تشيل المادة من الموضوع، وتبص لفكرة الإدمان بعين رجل أعمال، هتكتشف حاجة خطيرة جدًا:\\n\\nالعميل مش لازم يحب منتجك... المهم إن منتجك يخلي حياته أفضل لدرجة إنه يكره يرجع للوضع القديم.\\n\\nفي البداية، المنتج بيكون:\\n\\nاختيار.\\n\\nبعد شوية...\\n\\nيبقى عادة.\\n\\nولو المنتج ممتاز فعلًا، ممكن يتحول إلى:\\n\\nجزء أساسي من طريقة العميل في العمل والحياة.\\n\\nوهنا يبدأ البيزنس الحقيقي.\\n\\n---\\n\\nخليني أديك مثال بسيط.\\n\\nالإنترنت كان في البداية رفاهية.\\n\\nبعدها أصبح وسيلة للتواصل.\\n\\nثم أصبح وسيلة للعمل والتعليم والتجارة والخدمات.\\n\\nدلوقتي بالنسبة لملايين الناس:\\n\\nانقطاع الإنترنت مش مجرد إزعاج... ممكن يعطل شغل وحياة كاملة.\\n\\nإيه اللي حصل؟\\n\\nالإنترنت ما أجبرش الناس تعتمد عليه.\\n\\nهو ببساطة أضاف قيمة ضخمة لدرجة إن الاستغناء عنه أصبح صعبًا.\\n\\nودي واحدة من أذكى قواعد بناء المنتجات.\\n\\n---\\n\\n🧠 لا تجعل العميل مدمنًا على المنتج...\\n\\nاجعله مدمنًا على النتيجة.\\n\\nودي نقطة فارقة جدًا.\\n\\nلو العميل متعلق بك لأنك عامل له خصم...\\n\\nأول ما المنافس يعمل خصم أكبر، هيمشي.\\n\\nلو متعلق بك لأنك الأرخص...\\n\\nأول ما حد يبقى أرخص، هيمشي.\\n\\nلو متعلق بك لأنك قريب...\\n\\nحد غيرك ممكن يفتح فرع أقرب.\\n\\nلكن لو العميل متعلق بك لأنك:\\n\\nبتوفر له وقت.\\n\\nبتزود دخله.\\n\\nبتقلل مجهوده.\\n\\nبتحل له مشكلة حقيقية.\\n\\nبتخليه يشتغل بكفاءة أكبر.\\n\\nساعتها أنت بنيت حاجة أقوى من الولاء.\\n\\nأنت بنيت:\\n\\nقيمة يصعب استبدالها.\\n\\n---\\n\\nوهنا في سؤال أخطر:\\n\\nهل منتجك يجعل العميل أقوى... أم يجعله أكثر اعتمادًا عليك فقط؟\\n\\nالفرق بينهم هو الفرق بين:\\n\\nBusiness ذكي\\n\\nو\\n\\nBusiness استغلالي.\\n\\nأنا لا أريد عميلًا يخسر لكي أكسب.\\n\\nلأن العميل الذي يخسر بسببي...\\n\\nفي النهاية ستنخفض قدرته على الشراء مني.\\n\\nأنا عايز المعادلة العكسية:\\n\\nالعميل يكسب → أنا أكسب.\\n\\nالعميل ينمو → أنا أنمو.\\n\\nالعميل ينجح → أنا أصبح جزءًا من نجاحه.\\n\\nدي هي العلاقة التجارية التي تستحق أن تستمر.\\n\\n---\\n\\n🔥 وهنا بقى الفكرة اللي ناس كتير بتفوتها:\\n\\nأنت لا تبيع المنتج.\\n\\nأنت تبيع:\\n\\nالتحول الذي يحدث بعد المنتج.\\n\\nشركة عقارات لا تبيع \\\"متر مربع\\\".\\n\\nهي تبيع:\\n\\nقرارًا أفضل + أمانًا + موقعًا + فرصة استثمار.\\n\\nشركة نقل لا تبيع \\\"مشوارًا\\\".\\n\\nهي تبيع:\\n\\nوصولًا أسرع وأسهل.\\n\\nبرنامج إدارة لا يبيع \\\"Software\\\".\\n\\nهو يبيع:\\n\\nوقتًا أقل ضائعًا + أخطاء أقل + سيطرة أكبر على العمل.\\n\\nالمشكلة إن معظم أصحاب المشاريع يسألون:\\n\\n> \\\"إيه اللي أقدر أبيعه؟\\\"\\n\\nبينما السؤال الأذكى:\\n\\n> \\\"إيه النتيجة اللي أقدر أخلي العميل يحصل عليها بشكل أفضل من أي بديل؟\\\"\\n\\n---\\n\\nCEO RULE\\n\\nلا تبنِ منتجًا يخاف العميل أن يفقده.\\n\\nابنِ قيمة يخاف العميل أن يعود للحياة بدونها.\\n\\n---\\n\\n🎯 CEO CHALLENGE\\n\\nخذ منتجك أو خدمتك اليوم واكتب جملة واحدة:\\n\\n\\\"بعد ما العميل يستخدمنا، حياته تصبح أفضل لأن ______.\\\"\\n\\nلو مش قادر تكمل الجملة...\\n\\nفدي مش مشكلة في التسويق.\\n\\nدي علامة إنك محتاج تعيد التفكير في القيمة نفسها.\\n\\n---\\n\\n💬 سؤال اليوم\\n\\nلو اختفى منتجك من السوق غدًا...\\n\\nما الشيء الحقيقي الذي سيفتقده العميل؟\\n\\nمش اسم المنتج.\\n\\nمش اللوجو.\\n\\nمش السعر.\\n\\nالنتيجة.\\n\\n---\\n\\nوالآن فهمت ليه غيرت رأيي...\\n\\nمش هشتغل تاجر مخدرات.\\n\\nولا عايز العميل يكون محتاجني لأنه ضعيف.\\n\\nأنا عايزه يحتاجني لأنه أصبح أقوى بسببي.\\n\\nوده بالنسبة لي...\\n\\nأذكى نوع من الاعتماد في البيزنس.\\n\\n---\\n\\nCEO NOTES\\n\\nDon't make customers addicted to your product.\\n\\nMake them addicted to the result.\",\n      \"ideaOfTheDay\": \"\",\n      \"ceoChallenge\": \"\",\n      \"discussionQuestion\": \"\",\n      \"hashtags\": \"#CEONotes #CEO #CEOMindset #ريادة_الأعمال #القيادة #العمل_بذكاء #تطوير_الأعمال #التسويق #المبيعات #قيمة_العميل #تجربة_العميل #بناء_الشركات #التفكير_الاستراتيجي #BusinessMindset #BusinessStrategy #CustomerValue #CustomerExperience #Entrepreneurship #BusinessGrowth #WorkSmart #Leadership\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-10-05T03:47:02.000Z\",\n      \"category\": \"التسويق وقيمة العميل\",\n      \"tags\": [\n        \"قيمة العميل\",\n        \"النتائج\",\n        \"تجربة العميل\"\n      ],\n      \"archiveImported\": true,\n      \"sourcePageId\": \"115226621594988\",\n      \"sourcePostId\": \"115226621594988_984855377968511\",\n      \"sourceUrl\": \"https://www.facebook.com/1017895867997795/posts/984855377968511\",\n      \"sourcePublishedAt\": \"2026-10-05T03:47:02.000Z\",\n      \"sourceEvidence\": \"facebook_page_post\"\n    },\n    {\n      \"day\": 25,\n      \"title\": \"لما الرقم يتحسن… والشغل يسوء\",\n      \"article\": \"مش كل رقم بيطلع لفوق معناه إن الشغل بيتحسن. ممكن المبيعات تزيد والعميل يرجع يشتكي، وممكن عدد المكالمات يكبر من غير ما مشكلة واحدة تتحل. الخطر إننا ننبهر بالمؤشر وننسى النتيجة اللي اتعمل المؤشر علشان يقيسها. الإدارة مش إنك تطارد رقم حلو في التقرير؛ الإدارة إنك تفهم الرقم بيقول إيه، وإيه اللي مستخبي وراه. اسأل دايمًا: هل التحسن ده حسّ به العميل والفريق فعلًا؟\",\n      \"ideaOfTheDay\": \"الرقم وسيلة للفهم، مش شهادة نجاح لوحده.\",\n      \"ceoChallenge\": \"اختار مؤشر بتتابعه، وحط جنبه مؤشر جودة يكشف أثره الحقيقي.\",\n      \"discussionQuestion\": \"إيه المؤشر اللي ممكن يبان ممتاز بينما التجربة على الأرض مش ممتازة؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-11-06\",\n      \"category\": \"الإدارة والأداء\",\n      \"tags\": [\n        \"مؤشرات الأداء\",\n        \"تجربة العميل\",\n        \"جودة الخدمة\"\n      ]\n    },\n    {\n      \"day\": 26,\n      \"title\": \"لما التفويض مش ضعف.. ده استثمار\",\n      \"article\": \"كتير من المديرين بيشوفوا التفويض كأنه خروج من المسؤولية، أو دليل إنهم مش قادرين يمسكوا كل التفاصيل. لكن التفويض الذكي مش إنك ترمي المهمة على حد وتمشي؛ هو إنك تبني شخص يقدر يشيل مسؤولية، وتديله فرصة يتعلم ويكبر.\\n\\nلما المدير يصر يعمل كل حاجة بنفسه، وقته بيتسحب في تفاصيل يومية، ومبيلاقيش مساحة يركز على القرارات اللي بتحرك الشغل لقدام. وفي نفس الوقت، الفريق بيتعود يستنى التعليمات بدل ما يفكر ويقترح. المشكلة مش بالضرورة في قدرات الناس؛ ساعات المشكلة في مساحة الثقة والصلاحية اللي بنديهالهم.\\n\\nالتفويض الصح يبدأ باختيار الشخص المناسب، وتوضيح النتيجة المطلوبة وحدود الصلاحية، وتوفير المعلومات والأدوات. بعد كده دورك يبقى متابعة وتوجيه، مش تدخل في كل خطوة. ولو حصل خطأ، ناقشه باعتباره فرصة تعلم، مش سبب تسحب المهمة فورًا.\\n\\nالقائد اللي بيعمل كل حاجة بنفسه ممكن يبان مشغول طول الوقت، لكنه بيصنع نقطة اختناق حوالين نفسه. أما اللي بيفوض بوعي، فهو بيضاعف قدرة الفريق وبيجهز ناس تقدر تتحمل مسؤولية أكبر.\",\n      \"ideaOfTheDay\": \"التفويض تمكين.. مش تخليص.\",\n      \"ceoChallenge\": \"خلال الـ48 ساعة الجاية، اختار مهمة روتينية بتعملها بنفسك، وفوضها لشخص في فريقك. وضّح النتيجة والصلاحيات، وقدّم الدعم من غير ما تسحب منه المسؤولية.\",\n      \"discussionQuestion\": \"إيه أكتر حاجة بتصعّب عليك تفويض المهام: الخوف من الخطأ، ضعف الثقة، ولا عدم وضوح الصلاحيات؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة #تمكين_الفريق\",\n      \"status\": \"Published\",\n      \"publishedAt\": \"2026-11-07T18:47:11.607Z\",\n      \"imageUrl\": \"https://ceo-notes-ai.yasser-abdelaziz83.workers.dev/image/26\",\n      \"category\": \"القيادة\",\n      \"tags\": [\n        \"التفويض\",\n        \"تمكين الفريق\",\n        \"بناء الثقة\"\n      ]\n    },\n    {\n      \"day\": 27,\n      \"title\": \"لما الصمت بيسبق القرار.. ده مش تردد، ده تقدير\",\n      \"article\": \"كتير مننا بيفتكر إن سرعة اتخاذ القرار دليل على الكفاءة. بس الحقيقة، في مواقف كتير، الصمت والتفكير العميق قبل ما تقول أو تعمل أي حاجة بيكون علامة على تقدير للموقف. مش كل مشكلة ليها حل فوري، ومش كل رد فعل لازم يكون سريع. التأني بيخليك تشوف الصورة كاملة، وتفهم تبعيات قرارك. \\n\\nالفرق بين التردد والتفكير المنظم، إن التردد بيخليك متشتت، لكن التفكير المنظم بيخليك مركز. لو حسيت إنك محتاج وقت، خده. الموضوع مش في إنك تكون أسرع، الموضوع في إنك تكون أدق. \\n\\nالتواصل هنا مهم جداً. مش لازم تخبي إنك بتفكر، لكن أوضح إنك بتحاول تاخد القرار الصح. قول: \\\"محتاج شوية وقت عشان أجمع المعلومات\\\" أو \\\"عايز أفكر في الموضوع ده بعمق\\\". ده بيزرع الثقة، مش القلق. \\n\\nفي النهاية، القيادة مش بس في إصدار الأوامر، القيادة في إنك تعرف امتى تسكت وتفكر، وإمتى تتكلم وتتصرف. القرار المتأني، حتى لو اتأخر شوية، بيكون أقوى وأكثر فعالية.\",\n      \"ideaOfTheDay\": \"التفكير العميق قبل الفعل.. قوة مش ضعف.\",\n      \"ceoChallenge\": \"خلال الـ 48 ساعة الجاية، اختار قرار مهم كنت هتاخده بشكل سريع. أخد وقتك فيه، حلله بعمق، وقيّم النتائج المتوقعة. سجل ملاحظاتك.\",\n      \"discussionQuestion\": \"إزاي نقدر نزرع ثقافة التفكير المنظم والتأني في بيئة عمل سريعة الوتيرة؟\",\n      \"hashtags\": \"#CEO_Notes #CEO_Challenge #فكرة_اليوم #إدارة #قيادة #اتخاذ_القرار #تفكير_نقدي\",\n      \"publishedAt\": \"2026-11-07T21:42:03.981Z\",\n      \"status\": \"Published\",\n      \"imageUrl\": \"https://ceo-notes-ai.yasser-abdelaziz83.workers.dev/image/27\",\n      \"category\": \"القيادة\",\n      \"tags\": [\n        \"اتخاذ القرار\",\n        \"التفكير النقدي\",\n        \"التأني\"\n      ]\n    }\n  ]\n}";
