function normalizeEditorialFeed(feed){
 const fallback=JSON.parse(POSTS);
 const localPosts=Array.isArray(fallback?.posts)?fallback.posts:[];
 const byDay=new Map(localPosts.map(post=>[Number(post.day),post]));
 const sourcePosts=Array.isArray(feed?.posts)?feed.posts:[];
 const posts=sourcePosts.map(post=>{
  const local=byDay.get(Number(post?.day))||{};
  const suppliedTags=Array.isArray(post?.tags)&&post.tags.length?post.tags:[];
  const localTags=Array.isArray(local.tags)&&local.tags.length?local.tags:[];
  const hashtagText=Array.isArray(post?.hashtags)?post.hashtags.join(" "):String(post?.hashtags||"");
  const derivedTags=hashtagText.split(/\s+/).map(tag=>tag.replace(/^#/,"").replace(/_/g," ")).filter(tag=>tag&&!["CEO Notes","CEO Challenge","فكرة اليوم"].includes(tag));
  const tags=suppliedTags.length?suppliedTags:(localTags.length?localTags:[...new Set(derivedTags)]);
  return {...post,category:post.category||local.category||"غير مصنّف",tags};
 });
 return {...feed,posts};
}
async function latestFeed(origin){
 const key=cacheKey(origin,"/__ceo_notes_feed_cache");
 try{
  const upstream=await fetch(UPSTREAM,{headers:{"Accept":"application/json"},cf:{cacheTtl:0}});
  if(!upstream.ok)throw new Error("feed_unavailable");
  const parsed=JSON.parse(await upstream.text());
  const normalized=normalizeEditorialFeed(parsed);
  const body=JSON.stringify(normalized);
  try{await caches.default.put(key,new Response(body,{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"public, max-age="+CACHE_TTL,"X-Content-Type-Options":"nosniff"}}));}catch(e){}
  return normalized;
 }catch(e){
  try{const cached=await caches.default.match(key);if(cached)return normalizeEditorialFeed(JSON.parse(await cached.text()));}catch(cacheError){}
  return normalizeEditorialFeed(JSON.parse(POSTS));
 }
}
async function marketData(origin){
 const key=cacheKey(origin,"/__ceo_notes_markets_cache");
 let staleData=null;
 try{
  const cached=await caches.default.match(key);
  if(cached){
   const candidate=JSON.parse(await cached.text());
   const fetchedAt=Date.parse(candidate.fetchedAt||""),age=Date.now()-fetchedAt;
   if(Number.isFinite(age)&&age>=0&&age<=21600000)return {...candidate,stale:false};
   if(Number.isFinite(age)&&age>21600000&&age<=259200000)staleData=candidate;
  }
 }catch(e){}
 try{
  const urls=[
   "https://api.frankfurter.dev/v2/rates?base=USD&quotes=EGP,EUR,GBP,RUB,AED,SAR",
   "https://api.frankfurter.dev/v2/rates?base=XAU&quotes=USD,EGP"
  ];
  const responses=await Promise.all(urls.map(url=>fetch(url,{headers:{"Accept":"application/json"},cf:{cacheTtl:21600}})));
  if(responses.some(response=>!response.ok))throw new Error("reference_rates_unavailable");
  const [fx,gold]=await Promise.all(responses.map(response=>response.json()));
  if(!Array.isArray(fx)||!fx.length||!Array.isArray(gold)||!gold.length)throw new Error("reference_rates_empty");
  const date=[...fx,...gold].map(item=>item.date).filter(Boolean).sort().at(-1)||"";
  const data={date,fx,gold,source:"Frankfurter",frequency:"daily_reference",fetchedAt:new Date().toISOString(),stale:false};
  try{await caches.default.put(key,new Response(JSON.stringify(data),{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"public, max-age=259200","X-Content-Type-Options":"nosniff"}}));}catch(e){}
  return data;
 }catch(error){
  if(staleData)return {...staleData,stale:true,staleReason:"provider_unavailable",checkedAt:new Date().toISOString()};
  throw new Error("reference_rates_unavailable");
 }
}
function xml(value){return String(value??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;");}
function rss(feed){
 const posts=(Array.isArray(feed?.posts)?feed.posts:[]).filter(p=>p&&p.status!=="Draft"&&p.status!=="Reserved").sort((a,b)=>Number(b.day||0)-Number(a.day||0));
 const items=posts.map(p=>{
  const d=new Date(p.publishedAt||"");
  const pub=Number.isNaN(d.getTime())?"":`<pubDate>${d.toUTCString()}</pubDate>`;
  const link="https://ceo-notes.pages.dev/post/"+encodeURIComponent(String(p.day||""));
  const taxonomy=[p.category,...(Array.isArray(p.tags)?p.tags:[])].filter(Boolean).map(tag=>`<category>${xml(tag)}</category>`).join("");
  return `<item><title>${xml(p.title)}</title><link>${xml(link)}</link><guid isPermaLink="false">ceo-notes-day-${xml(p.day)}</guid><description>${xml(p.article)}</description>${taxonomy}${pub}</item>`;
 }).join("");
 return `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>CEO Notes</title><link>https://ceo-notes.pages.dev/</link><description>أفكار عملية عن القيادة والإدارة والعمل الذكي.</description><language>ar</language>${items}</channel></rss>`;
}
function sitemap(feed){
 const posts=(Array.isArray(feed?.posts)?feed.posts:[]).filter(p=>p&&p.status!=="Draft"&&p.status!=="Reserved");
 const urls=['<url><loc>https://ceo-notes.pages.dev/</loc></url>',...posts.map(p=>'<url><loc>https://ceo-notes.pages.dev/post/'+encodeURIComponent(String(p.day))+'</loc></url>')].join("");
 return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>';
}
function articleHtml(post){
 const title=xml((post.title||"CEO Notes")+" | CEO Notes");
 const description=xml(String(post.article||"").replace(/\s+/g," ").slice(0,155));
 const canonical="https://ceo-notes.pages.dev/post/"+encodeURIComponent(String(post.day));
 const image=typeof post.imageUrl==="string"&&post.imageUrl.startsWith("https://")?xml(post.imageUrl):"";
 const published=post.publishedAt&&!Number.isNaN(new Date(post.publishedAt).getTime())?xml(new Date(post.publishedAt).toISOString()):"";
 const section=xml(post.category||"");
 return HTML.replace(/<title>[\s\S]*?<\/title>/,'<title>'+title+'</title>')
  .replace(/<meta name="description" content="[^"]*">/,'<meta name="description" content="'+description+'">')
  .replace(/<meta property="og:type" content="[^"]*">/,'<meta property="og:type" content="article">')
  .replace(/<meta property="og:title" content="[^"]*">/,'<meta property="og:title" content="'+title+'">')
  .replace(/<meta property="og:description" content="[^"]*">/,'<meta property="og:description" content="'+description+'">')
  .replace(/<meta property="og:url" content="[^"]*">/,'<meta property="og:url" content="'+canonical+'">')
  .replace(/<meta property="og:image" content="[^"]*">/,'<meta property="og:image" content="'+image+'">')
  .replace(/<meta property="article:published_time" content="[^"]*">/,'<meta property="article:published_time" content="'+published+'">')
  .replace(/<meta property="article:section" content="[^"]*">/,'<meta property="article:section" content="'+section+'">')
  .replace(/<meta name="twitter:card" content="[^"]*">/,'<meta name="twitter:card" content="'+(image?"summary_large_image":"summary")+'">')
  .replace(/<meta name="twitter:title" content="[^"]*">/,'<meta name="twitter:title" content="'+title+'">')
  .replace(/<meta name="twitter:description" content="[^"]*">/,'<meta name="twitter:description" content="'+description+'">')
  .replace(/<meta name="twitter:image" content="[^"]*">/,'<meta name="twitter:image" content="'+image+'">')
  .replace(/<link rel="canonical" href="[^"]*">/,'<link rel="canonical" href="'+canonical+'">');
}
const XML_HEADERS={"Content-Type":"application/xml; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"};
const HTML_HEADERS={"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=60, s-maxage=300","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","X-Frame-Options":"DENY"};
export default {async fetch(request){
 const url=new URL(request.url);
 if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method Not Allowed",{status:405});
 if(url.pathname==="/radio.css")return new Response(request.method==="HEAD"?null:RADIO_CSS,{headers:{"Content-Type":"text/css; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});
 if(url.pathname==="/radio.js")return new Response(request.method==="HEAD"?null:RADIO_JS,{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"public, max-age=300","X-Content-Type-Options":"nosniff"}});

 if(url.pathname==="/feed"){
  const data=await latestFeed(url.origin);
  return new Response(JSON.stringify(data),{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
 }
 if(url.pathname==="/markets"){
  try{
   const data=await marketData(url.origin),headers={"Content-Type":"application/json; charset=utf-8","Cache-Control":data.stale?"public, max-age=60":"public, max-age=300","X-Content-Type-Options":"nosniff","X-Data-Stale":String(Boolean(data.stale))};
   if(data.stale)headers.Warning='110 - "Response is stale"';
   return new Response(JSON.stringify(data),{headers});
  }catch(e){return new Response(JSON.stringify({error:"market_data_unavailable",message:"Daily reference rates are temporarily unavailable."}),{status:503,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});}
 }
 if(url.pathname==="/rss.xml")return new Response(rss(await latestFeed(url.origin)),{headers:XML_HEADERS});
 if(url.pathname==="/robots.txt")return new Response("User-agent: *\nAllow: /\nSitemap: https://ceo-notes.pages.dev/sitemap.xml\n",{headers:{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"public, max-age=3600"}});
 if(url.pathname==="/sitemap.xml")return new Response(sitemap(await latestFeed(url.origin)),{headers:XML_HEADERS});
 const articleMatch=url.pathname.match(/^\/post\/(\d+)\/?$/);
 if(articleMatch){
  const feed=await latestFeed(url.origin),day=Number(articleMatch[1]);
  const post=(Array.isArray(feed.posts)?feed.posts:[]).find(p=>Number(p.day)===day&&p.status!=="Draft"&&p.status!=="Reserved");
  if(!post)return new Response("Article Not Found",{status:404,headers:{"Content-Type":"text/plain; charset=utf-8","X-Content-Type-Options":"nosniff"}});
  return new Response(request.method==="HEAD"?null:articleHtml(post),{headers:HTML_HEADERS});
 }
 if(url.pathname==="/"||url.pathname==="/index.html")return new Response(request.method==="HEAD"?null:HTML,{headers:HTML_HEADERS});
 if(url.pathname==="/posts.json")return new Response(POSTS,{headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff"}});
 return new Response("Not Found",{status:404,headers:{"X-Content-Type-Options":"nosniff"}});
}};